    /**
     * Loads and parses the morph targets file.
     */
    async _loadMorphTargets() {
      const morphTargets = await loadMorphTargets(this._patient.morphTargetsUrl);
      this._morphTargets = {};
      this._catalogMorphTargets = {};
      for (const areaName in morphTargets)
        if (this.#isCatalogArea(morphTargets, areaName)) {
          this._catalogMorphTargets[areaName] = morphTargets[areaName];
        } else {
          this._morphTargets[areaName] = morphTargets[areaName];
        }
      Debugger.debug(Level.SIMULATOR, () => this.#logMorphTargets());
    }
