      checkTypes(arguments, ["Array"]);
      if (simulationIds.length < 2)
        return true;
      const model = this.getSimulationModel(simulationIds[0]);
      for (let i3 = 1, length = simulationIds.length; i3 < length; i3++) {
        if (!this.getSimulationModel(simulationIds[i3]).equals(model))
          return false;
      }
      return true;
