    /**
     * Exports the simulation parameters of a parameter viewport as an object.
     * @param {string} simulationId Simulation identifier.
     * @returns {Promise<SimulationData>}
     */
    async exportSimulationParameters(simulationId) {
      const model = this.getSimulationModel(simulationId);
      const exportObject = {
        simulationType: model.type.description,
        procedures: {}
      };
      await Promise.all(this._tools.map(async (tool) => {
        const exported = await tool.export(model);
        if (exported === null) return;
        if (tool.exportName === BLEPHAROPLASTY_TOOL_EXPORT_NAME) {
          const lineTool = this._getTool(FREE_LINE_TOOL_ID);
          const deformation = lineTool.exportCustomDeformations(model, CustomDeformationId.EYELID_LIFT);
          if (deformation) exported.eyelidLift = deformation;
        }
        exportObject.procedures[tool.exportName] = exported;
      }));
      return exportObject;
    }
    /**
     * Imports simulation data to proper tools.
     * If the simulation is not editable, only tools that do not modify the mesh.
     * @param {string} simulationId Simulation identifier.
     * @param {SimulationData} jsonObject Object that contains all import data.
     * @returns {Promise<void>}
     */
    async importSimulationParameters(simulationId, jsonObject) {
      const simulation = this._getSimulation(simulationId);
      const model = simulation.model;
      if (jsonObject.simulationType !== model.type.description) throw new Error("Simulation type mismatch");
      if (jsonObject.procedures === void 0) return;
      await Promise.all(this._tools.map(async (tool) => {
        if (!simulation.editable && tool.editType !== ToolEditType.NONE) return;
        const toolData = jsonObject.procedures[tool.exportName];
        if (toolData === void 0) return;
        if (tool.exportName === BLEPHAROPLASTY_TOOL_EXPORT_NAME) {
          const eyelidLift = toolData.eyelidLift;
          if (eyelidLift !== void 0) {
            const lineTool = this._getTool(FREE_LINE_TOOL_ID);
            lineTool.importCustomDeformations(model, eyelidLift, CustomDeformationId.EYELID_LIFT);
          }
        }
        await tool.import(model, toolData);
      }));
    }
