    /**
     * Resets remap areolae parameters for a given simulation.
     * @param {string} simulationId Simulation identifier.
     * @returns {Promise}
     */
    #resetRemapAreolaeProcedure(simulationId) {
      const simulationProperties = this.getSimulationProperties(simulationId);
      simulationProperties.areolaRadii.left = this._patient.areolaRadii.left;
      simulationProperties.areolaRadii.right = this._patient.areolaRadii.right;
      return this._updateProcedure(
        simulationId,
        {
          id: REMAP_AREOLAE_TOOL_ID,
          merge: true,
          parameters: {
            left: {
              areolaDiameter: this._patient.areolaRadii.left * 2,
              simulate: false
              // no need to remap when resetting the procedure
            },
            right: {
              areolaDiameter: this._patient.areolaRadii.right * 2,
              simulate: false
              // no need to remap when resetting the procedure
            }
          }
        }
      );
    }
    /**
     * Resets scars parameters for a given simulation.
     * @param {string} simulationId Simulation identifier.
     * @returns {Promise}
     */
    #resetScarProcedure(simulationId) {
      const defaultIncisionType = BreastIncisionType.NONE;
      const simulationProperties = this.getSimulationProperties(simulationId);
      const mastopexyProperties = simulationProperties.mastopexy;
      mastopexyProperties.left.incisionType = defaultIncisionType;
      mastopexyProperties.right.incisionType = defaultIncisionType;
      return this._updateProcedure(
        simulationId,
        {
          id: SCAR_TOOL_ID,
          merge: true,
          parameters: {
            left: {
              incisionType: defaultIncisionType
            },
            right: {
              incisionType: defaultIncisionType
            }
          }
        }
      );
    }
