      const netVolume = implantVolume * correction - reductionVolume;
      this.#implantVolumeRatio = MathUtils.clamp(netVolume / maxVolume, 0, 1);
      this.#breastVolumeRatio = MathUtils.clamp((netVolume + originalVolume) / (maxVolume + originalVolume), 0, 1);
