      this.#updateBezierCurve3D(this.#bottomPoint, this.#bottomControlPoint, this.#nipplePoint);
      const verticalLowerLen = this.#bezierCurve3D.length();
      this.#updateBezierCurve3D(this.#outerPoint, this.#outerControlPoint, this.#nipplePoint);
      const horizontalOuterLen = this.#bezierCurve3D.length();
      this.#updateBezierCurve3D(this.#innerPoint, this.#innerControlPoint, this.#nipplePoint);
      const horizontalInnerLen = this.#bezierCurve3D.length();
      this.#tFactorVerticalUpper = 1 - verticalDisplacement / verticalUpperLen;
      this.#tFactorVerticalLower = 1 + verticalDisplacement / verticalLowerLen;
