      currentNipplePosition.add(this.#verticalDisplacement).add(this.#horizontalDisplacement);
      this.#displacement.subVectors(currentNipplePosition, originalNipplePosition);
      this.#displacement.multiplyScalar(this.#confidence);
      currentNipplePosition.copy(originalNipplePosition).add(this.#displacement);
