    /**
     * Initializes the line points arrays (memory optimization).
     * @param {number[][]} linesIndices Vertex indices array for each line.
     */
    #initializeLinePoints(linesIndices) {
      const linePoints = new Array(linesIndices.length);
      for (let i3 = 0; i3 < linesIndices.length; i3++) {
        linePoints[i3] = new Array(linesIndices[i3].length);
        for (let j = 0; j < linesIndices[i3].length; j++) {
          linePoints[i3][j] = new Vector3();
        }
      }
      return linePoints;
    }
    /**
     * Creates the line objects.
     * @param {object} parent Parent object of the lines.
     * @param {number} amount Amount of lines.
     */
    #createLineObjects(parent, amount) {
      const lineObjects = new Array(amount);
      for (let i3 = 0; i3 < amount; i3++) {
        const lineMaterial = new MeshLineMaterial({
          color: CURVE_LINE_COLOR,
          transparent: true,
          lineWidth: CURVE_LINE_WIDTH,
          sizeAttenuation: true
          // width is not in pixels
        });
        const lineObject = new Mesh(new MeshLineGeometry(), lineMaterial);
        parent.add(lineObject);
        lineObjects[i3] = lineObject;
      }
      return lineObjects;
    }
    /**
     * Updates the line objects according to their corresponding vertices positions.
     * @param {number[][]} linesIndices Vertex indices array for each line.
     * @param {Mesh[]} lineObjects The line objects to update.
     * @param {Vector3[][]} linesPoints Structure where computed line points are saved (memory optimization).
     * @param {Model} model Current simulation model with the reference vertices.
     */
    #updateLineObjects(linesIndices, lineObjects, linesPoints, model) {
      for (let i3 = 0; i3 < linesIndices.length; i3++) {
        for (let j = 0; j < linesIndices[i3].length; j++) {
          linesPoints[i3][j].copy(model.getVertexPosition(linesIndices[i3][j]));
          linesPoints[i3][j].addScaledVector(model.getVertexNormal(linesIndices[i3][j]), CURVE_LINE_OFFSET);
        }
        lineObjects[i3].geometry.setPoints(linesPoints[i3]);
      }
    }
