  // app/javascript/helpers/sliders.js
  function sliderGradient() {
    findAll("input[type=range]").forEach((input) => {
      input.style.setProperty("--mediumpercentage", 0);
      input.style.setProperty("--lastmedium", 0);
      input.style.setProperty("--initial", "0");
      input.style.setProperty("--direction", "to right");
      findParent(input, ".slider-value")?.style.setProperty("--percentageoutput", input.value * 100);
      input.style.setProperty("--percentage", 0);
      findParent(input, ".slider--horizontal")?.style.setProperty("--opacitydot", "0");
      setSliderAttributes(input);
      setSliderVars(input);
      on(input, "input", () => {
        setSliderAttributes(input);
        setSliderVars(input);
      });
    });
  }
  function setSliderAttributes(input) {
    if (!hasClass(input, "slider-procedures")) return;
    const initial = parseFloat(data(input, "initial"));
    if (initial === 50) {
      attr(input, "step", 5e-3);
    } else {
      const currentStep = attr(input, "step");
      attr(input, "step", 0.01);
      if (currentStep == 5e-3) input.value -= 0.01;
    }
  }
  function setSliderVars(input) {
    const initial = parseFloat(data(input, "initial"));
    const inputContainer = findParent(input, ".slider--horizontal");
    let initialPercentage = 0;
    let percentage = calculatePercentage(input, initial);
    let mediumpercentage = 0;
    let direction2 = "to right";
    let lastmedium = 0;
    let outputValue = input.value * 100;
    inputContainer?.style.setProperty("--opacitydot", "0");
    if (initial === 50) {
      const trackSize = 2;
      if (percentage <= 0) direction2 = "to left";
      percentage = Math.abs(percentage) / 2 + 50;
      mediumpercentage = percentage;
      lastmedium = 100;
      initialPercentage = initial;
      outputValue -= initial;
      outputValue *= trackSize;
      inputContainer?.style.setProperty("--opacitydot", "1");
    }
    if (initial === 100) {
      direction2 = "to left";
      percentage = 100 - percentage;
      outputValue -= initial;
    }
    insertHTML(`#${currentProcedure}-output`, input.value * 100 === initial ? "" : parseInt(outputValue));
    input.style.setProperty("--direction", direction2);
    input.style.setProperty("--initial", initialPercentage);
    input.style.setProperty("--mediumpercentage", mediumpercentage);
    input.style.setProperty("--lastmedium", lastmedium);
    input.style.setProperty("--percentage", percentage);
    findParent(input, ".slider-value")?.style.setProperty("--percentageoutput", input.value * 100);
  }
  function calculatePercentage(input, initial) {
    const min4 = parseFloat(input.min);
    const max3 = parseFloat(input.max);
    let sliderSize;
    let valuePercentage;
    let percentage;
    if (max3 === 100 && min4 === -100 && (initial === 100 || initial === 0)) return (input.value - min4) / (max3 - min4) * 100;
    if (min4 > 0 || max3 < 0) {
      sliderSize = Math.abs(max3) - Math.abs(min4);
      valuePercentage = input.value - min4;
    } else {
      sliderSize = Math.abs(min4) + Math.abs(max3);
      valuePercentage = input.value;
    }
    if (initial == 50) sliderSize /= 2;
    else valuePercentage = Math.abs(valuePercentage);
    percentage = valuePercentage / sliderSize * 100;
    if (max3 == 0 && initial == 0) percentage = 100 - percentage;
    return percentage;
  }
  function resetSlider(name51, defaultValue, output = false) {
    const input = find(`#${name51}`);
    if (!input) return;
    input.value = defaultValue;
    if (output) find(`.${name51}-output`).innerHTML = output;
    setSliderVars(input);
  }

