  // app/javascript/components/my_color_picker.js
  var import_huebee = __toESM(require_huebee());
  var MyColorPicker = class {
    constructor(element, config5) {
      if (!element) return;
      this.initColors();
      this.element = element;
      this.defaultConfig = {
        huebeeConfigs: {
          notation: "hex",
          saturations: 1,
          shades: 0,
          customColors: this.schemeColors
        },
        defaultColor: "#137191",
        darkMode: false,
        brightLimit: 0.7,
        brightTextSelector: ".too-bright-text",
        lengthTextSelector: null,
        customOnChangeColor: null,
        afterSelect: null
      };
      this.config = Object.assign({}, this.defaultConfig, config5);
      this.addListeners();
    }
    get target() {
      return data(this.element, "target");
    }
    get brightness() {
      return this.huebee.lum - Math.cos((this.huebee.hue + 70) / 180 * Math.PI) * 0.15;
    }
    get brightText() {
      return [
        this.element.parentElement.querySelector(this.config.brightTextSelector),
        this.element.parentElement.parentElement.querySelector(this.config.brightTextSelector)
      ].find((el) => el);
    }
    initColors() {
      this.schemeColors = [
        "#C40000",
        "#C46200",
        "#C4C400",
        "#62C400",
        "#00C400",
        "#00C462",
        "#00C4C4",
        "#0062C4",
        "#0000C4",
        "#6200C4",
        "#C400C4",
        "#C40062",
        "#9D0000",
        "#9D4E00",
        "#9D9D00",
        "#4E9D00",
        "#009D00",
        "#009D4E",
        "#009D9D",
        "#004E9D",
        "#00009D",
        "#4E009D",
        "#9D009D",
        "#9D004E",
        "#760000",
        "#763B00",
        "#767600",
        "#3B7600",
        "#007600",
        "#00763B",
        "#007676",
        "#003B76",
        "#000076",
        "#3B0076",
        "#760076",
        "#76003B",
        "#4E0000",
        "#4E2700",
        "#4E4E00",
        "#274E00",
        "#004E00",
        "#004E27",
        "#004E4E",
        "#00274E",
        "#00004E",
        "#27004E",
        "#4E004E",
        "#4E0027"
      ];
    }
    reset() {
      this.setColor(this.config.defaultColor);
      this.element.style.color = "white";
    }
    addListeners() {
      this.huebee = new import_huebee.default(this.element, this.config.huebeeConfigs);
      this.setColor(this.element.value);
      on(this.element, "input", (e3) => this.onChange(e3.target.value));
      this.huebee.on("change", (color) => this.onChange(color));
      on(".btn--color-reset", "click", () => {
        this.reset();
      });
    }
    onChange(color) {
      if (typeof this.config.customOnChangeColor === "function")
        this.config.customOnChangeColor();
      else
        this.setColor(color);
      if (typeof this.config.afterSelect === "function")
        this.config.afterSelect();
    }
    setColor(color) {
      if (color.length == 6 && !color.startsWith("#")) color = "#" + color;
      document.documentElement.style.setProperty("--my-primary-color", hexToRgb(color));
      document.documentElement.style.setProperty("--review-template-overlay-color", hexToRgb(color, "0.5"));
      this.element.value = color;
      this.element.style.backgroundColor = color;
      if (this.huebee) {
        this.huebee.setColor(color);
        this.validateColor(color);
      }
    }
    validateColor(color) {
      const validFormat = color == this.huebee.color && color.length === 7;
      const validBrightness = this.validateBrightness();
      toggleClass(this.brightText, "hide", validBrightness);
      if (find(this.config.lengthTextSelector))
        toggleClass(this.config.lengthTextSelector, "hide", validFormat);
      if (!this.target) return;
      if (validBrightness && validFormat) {
        removeAttr(this.target, "disabled");
      } else {
        attr(this.target, "disabled", "disabled");
      }
    }
    validateBrightness() {
      if (this.colorFromSelection()) return true;
      if (this.config.darkMode)
        return this.brightness > this.config.brightLimit;
      else
        return this.brightness <= this.config.brightLimit;
    }
    colorFromSelection() {
      const isDefaultColor = this.huebee.color == this.config.defaultColor;
      const isPaletteColor = this.huebee.options.customColors && this.huebee.options.customColors.includes(this.huebee.color);
      return isDefaultColor || isPaletteColor;
    }
  };

