      observer.observe(find(".skin-section-js"), { attributes: true, childList: false, subtree: false, attributeFilter: ["class"], attributeOldValue: true });
      observer.observe(find(".simulator"), { attributes: true, childList: false, subtree: false, attributeFilter: ["class"], attributeOldValue: true });
