  // app/javascript/components/viewer/breast/breast_info_manager.js
  var BreastInfoManager = class extends InfoManager {
    constructor(references) {
      super(references);
    }
    initialize() {
      super.initialize();
    }
    printRows(infoObj) {
      const cm = ["diameter", "width", "height"];
      const cc = ["volume", "fat"];
      const omited = ["asymmetry", "implant_id"];
      const translatedValues = ["shape", "placement"];
      const ordered = ["brand", "shape", "profile", "reference", "volume", "diameter", "projection", "width", "height", "fat", "placement"];
      if (infoObj["volume"] === 0) omited.push("shape", "placement", "width", "height", "diameter", "projection");
      if (infoObj["shape"] === "round") omited.push("width", "height");
      else if (infoObj["shape"] === "anatomical") omited.push("diameter");
      let rows = "";
      for (const key of ordered) {
        if (omited.includes(key)) continue;
        if (!Object.keys(infoObj).includes(key)) continue;
        let value = infoObj[key];
        if (key == "fat") {
          rows += this.fatRow(value);
          continue;
        }
        if (cm.includes(key)) value = `${value} cm`;
        else if (cc.includes(key)) value = `${value} cc`;
        if (key != "placement" || key == "placement" && ["dual-plane", "submuscular", "subglandular"].includes(value)) {
          if (value === "dual-plane") value = "dualPlane";
          if (translatedValues.includes(key)) value = translations[value];
        }
        rows += render("viewerInfoRow", { label: translations[key], value });
      }
      return rows;
    }
    printPdfRows(leftInfo, rightInfo) {
      const cm = ["diameter", "width", "height", "projection"];
      const cc = ["volume", "fat"];
      const omited = ["asymmetry", "implant_id"];
      const translatedValues = ["shape", "placement"];
      const ordered = ["brand", "shape", "profile", "reference", "volume", "diameter", "projection", "width", "height", "fat", "placement"];
      const bothZeroVolume = leftInfo.volume === 0 && rightInfo.volume === 0;
      const bothRound = leftInfo.shape === "round" && rightInfo.shape === "round";
      const bothAnatomical = leftInfo.shape === "anatomical" && rightInfo.shape === "anatomical";
      if (bothZeroVolume) {
        omited.push("shape", "placement", "width", "height", "diameter", "projection");
      } else if (bothRound) {
        omited.push("width", "height");
      } else if (bothAnatomical) {
        omited.push("diameter");
      }
      const keys = ordered.filter(
        (key) => !omited.includes(key) && (key in leftInfo || key in rightInfo)
      );
      let rows = "";
      for (const key of keys) {
        let leftValue = leftInfo[key] ?? "";
        let rightValue = rightInfo[key] ?? "";
        const formatValue = (value) => {
          if (!value) return "";
          if (cm.includes(key)) value = `${value} cm`;
          else if (cc.includes(key)) value = `${value} cc`;
          if (key !== "placement" || ["dual-plane", "submuscular", "subglandular"].includes(value)) {
            if (value === "dual-plane") value = "dualPlane";
            if (translatedValues.includes(key)) value = translations[value];
          }
          return value;
        };
        rows += render("viewerPdfInfoRow", { label: translations[key], leftValue: formatValue(leftValue), rightValue: formatValue(rightValue) });
      }
      return rows;
    }
    fatRow(value) {
      const label = value < 0 ? translations.fatRemoved : translations.fatAdded;
      return render("viewerInfoRow", { label, value: `${Math.abs(value)} cc` });
    }
    printTable(simulatedCanvas, container) {
      const asymmetry = simulatedCanvas?.asymmetry || false;
      const volumeChange = !!(simulatedCanvas?.right?.volume || simulatedCanvas?.left?.volume);
      const fatChange = !!(simulatedCanvas?.right?.fat || simulatedCanvas?.left?.fat);
      insertHTML(`${container} .info__title`, simulatedCanvas["name"]);
      insertHTML(`${container} .info__table-wrapper`, render("viewerInfoTable", { asymmetry, leftText: translations.leftBreast, rightText: translations.rightBreast, breastText: translations.breast, breastChanges: volumeChange || fatChange, fullbody: this.viewer.isBody() }));
      if (volumeChange || fatChange) {
        if (asymmetry) {
          insertHTML(`${container} .info__table--left`, this.printRows(simulatedCanvas["left"]));
          insertHTML(`${container} .info__table--right`, this.printRows(simulatedCanvas["right"]));
        } else {
          insertHTML(`${container} .info__table--main`, this.printRows(simulatedCanvas["left"]));
        }
      }
    }
  };

