        const lowerThirdFilter = (metric) => !find("#measurements-lower-third").checked && (metric.description.includes("e_line") || metric.description.includes("mouth_width_distance"));
        this.metrics = this.metrics.filter((metric) => !anglesFilter(metric) && !distancesFilter(metric) && !lowerThirdFilter(metric));
        if (this.metrics.includes(MeasurementType.MOUTH_WIDTH_DISTANCE)) this.metrics.push(MeasurementType.STOMION_MENTON_DISTANCE);
