      const originalGarment = !!this.variants[garment] ? this.variants[garment].original : garment;
      const variant = !!this.variants[garment] ? this.variants[garment].variant : 0;
      color = color ? color : data(`.colors__color--clothes[data-value="${this.selectedColor[this.selectedTab]}"]`, "hex");
      await engine.showGarment(canvas, { garmentId: originalGarment, enable: show2, color, variantIndex: variant });
