  // app/javascript/components/viewer/breast/lipofilling_manager.js
  var LipofillingManager = class {
    constructor() {
    }
    initialize(references) {
      this.references = references;
      this.viewer = this.references.viewer;
      this.simulator = this.references.simulator;
      this.inputManager = this.references.inputManager;
      this.simulationsManager = this.references.simulationsManager;
      this.messageManager = this.references.messageManager;
      this.boundaries = {};
      this.parameters = {
        right: {
          topInnerVolume: 0,
          topOuterVolume: 0,
          bottomInnerVolume: 0,
          bottomOuterVolume: 0,
          beautify: false,
          volumeCorrection: 0
        },
        left: {
          topInnerVolume: 0,
          topOuterVolume: 0,
          bottomInnerVolume: 0,
          bottomOuterVolume: 0,
          beautify: false,
          volumeCorrection: 0
        }
      };
      on(".lipofilling__button", "click", (e3) => {
        removeClass(".lipofilling__button", "selected");
        this.selectRow(data(e3.currentTarget, "area"));
      });
      on(".input-group--fat .btn-control-js", "click", async (e3) => {
        const input = hasClass(e3.currentTarget, "btn--plus") ? "lipofilling_add" : "lipofilling_sub";
        await this.simulator.simulate(+find("input#breast_volume").value, () => {
          this.updateQuadrants();
        }, input);
      });
      on("#lipofilling-beautify", "change", () => {
        this.simulator.simulate(+find("input#breast_volume").value, () => {
        }, "lipofilling_beautify");
      });
      on(".modal-reset-lipofilling-js", "click", () => {
        this.reset();
        this.references.modalManager.close();
        this.messageManager.snackbar(translations.lipofillingReset);
      });
      on(".lipofilling__reset", "click", () => {
        this.references.modalManager.open("reset-lipofilling");
      });
    }
    setParams(input) {
      if (input == "lipofilling_reset") {
        this.resetParams();
      } else if (["lipofilling_add", "lipofilling_sub"].includes(input)) {
        const areas = this.getSelectedAreas();
        const value = +find("input#breast_fat").value;
        for (const area of areas) {
          if (input == "lipofilling_add")
            this.parameters[area.side][`${area.quadrant}Volume`] = this.parameters[area.side][`${area.quadrant}Volume`] + value;
          else
            this.parameters[area.side][`${area.quadrant}Volume`] = this.parameters[area.side][`${area.quadrant}Volume`] - value;
        }
      }
      const volumeCorrection = normalizeCustomSimulationValue(+find("#breast_volume_correction").value);
      this.parameters["left"]["volumeCorrection"] = volumeCorrection;
      this.parameters["right"]["volumeCorrection"] = volumeCorrection;
      this.parameters["left"]["beautify"] = this.withChangesBySide("left") ? find("#lipofilling-beautify").checked : false;
      this.parameters["right"]["beautify"] = this.withChangesBySide("right") ? find("#lipofilling-beautify").checked : false;
      this.updateUI();
    }
    toggleButtons() {
      const selected = find(".lipofilling__button.selected");
      const asymmetry = this.inputManager.getValue("lipofilling_asymmetry");
      toggleClass('.lipofilling__button[data-side="left"]', "disabled", asymmetry == "right");
      toggleClass('.lipofilling__button[data-side="right"]', "disabled", asymmetry == "left");
      removeClass(".lipofilling__button.disabled", "selected");
      if (selected) this.selectRow(data(selected, "area"));
    }
    selectRow(area) {
      addClass(`.lipofilling__button[data-area="${area}"]:not(.disabled)`, "selected");
      this.checkMax();
    }
    total() {
      let result = { right: 0, left: 0 };
      for (const side in this.parameters) {
        for (const area in this.parameters[side]) {
          if (area === "beautify" || area === "volumeCorrection") continue;
          result[side] += this.parameters[side][area];
        }
      }
      return result;
    }
    withChanges() {
      return this.withChangesBySide("right") || this.withChangesBySide("left");
    }
    withChangesBySide(side) {
      for (const area in this.parameters[side]) {
        if (area === "beautify" || area === "volumeCorrection") continue;
        if (this.parameters[side][area] !== 0) return true;
      }
      return false;
    }
    resetParams() {
      const volumeCorrection = normalizeCustomSimulationValue(+find("#breast_volume_correction").value);
      this.parameters = {
        right: {
          topInnerVolume: 0,
          topOuterVolume: 0,
          bottomInnerVolume: 0,
          bottomOuterVolume: 0,
          beautify: false,
          volumeCorrection
        },
        left: {
          topInnerVolume: 0,
          topOuterVolume: 0,
          bottomInnerVolume: 0,
          bottomOuterVolume: 0,
          beautify: false,
          volumeCorrection
        }
      };
    }
    async reset() {
      await this.simulator.simulate(+find("input#breast_volume").value, () => {
        this.updateQuadrants();
      }, "lipofilling_reset");
    }
    updateUI() {
      const total = this.total();
      find(".lipofilling__total .lipofilling__number").innerHTML = total.left + total.right;
      toggleClass(".lipofilling__reset", "disabled", !this.withChanges());
      this.checkMax();
    }
    updateQuadrants() {
      const afterValues = this.viewer.engine.getLipofillingQuadrantVolumes("afterCanvas1", this.total());
      [...findAll(".lipofilling__buttons .lipofilling__number")].forEach((elem2) => {
        const area = data(elem2, "area");
        const side = data(elem2, "side");
        const value = afterValues[side][`${area}Volume`].toFixed(1);
        insertHTML(elem2, value);
      });
    }
    setBoundaries() {
      const computedProperties = engine.computeBreastProperties("beforeCanvas");
      this.boundaries = {
        min: {
          right: {
            bottomInnerVolume: -computedProperties.right.bottomInnerVolume,
            bottomOuterVolume: -computedProperties.right.bottomOuterVolume,
            topInnerVolume: -computedProperties.right.topInnerVolume,
            topOuterVolume: -computedProperties.right.topOuterVolume
          },
          left: {
            bottomInnerVolume: -computedProperties.left.bottomInnerVolume,
            bottomOuterVolume: -computedProperties.left.bottomOuterVolume,
            topInnerVolume: -computedProperties.left.topInnerVolume,
            topOuterVolume: -computedProperties.left.topOuterVolume
          }
        },
        max: {
          right: {
            bottomInnerVolume: Math.max(computedProperties.right.bottomInnerVolume, 100),
            bottomOuterVolume: Math.max(computedProperties.right.bottomOuterVolume, 100),
            topInnerVolume: Math.max(computedProperties.right.topInnerVolume, 100),
            topOuterVolume: Math.max(computedProperties.right.topOuterVolume, 100)
          },
          left: {
            bottomInnerVolume: Math.max(computedProperties.left.bottomInnerVolume, 100),
            bottomOuterVolume: Math.max(computedProperties.left.bottomOuterVolume, 100),
            topInnerVolume: Math.max(computedProperties.left.topInnerVolume, 100),
            topOuterVolume: Math.max(computedProperties.left.topOuterVolume, 100)
          }
        }
      };
    }
    checkMax() {
      const areas = this.getSelectedAreas();
      removeClass(".input-group--fat .btn-control-js.btn--plus", "disabled");
      removeClass(".input-group--fat .btn-control-js.btn--minus", "disabled");
      areas.forEach((area) => {
        this.checkMaxBySide(`${area.quadrant}Volume`, area.side);
      });
    }
    checkMaxBySide(quadrant2, side) {
      if (!this.boundaries.max) return;
      if (this.parameters[side][quadrant2] >= this.boundaries.max[side][quadrant2]) addClass(".input-group--fat .btn-control-js.btn--plus", "disabled");
      else if (this.parameters[side][quadrant2] <= this.boundaries.min[side][quadrant2]) addClass(".input-group--fat .btn-control-js.btn--minus", "disabled");
    }
    getSelectedAreas() {
      return [...findAll(".lipofilling__button.selected")].map((btn) => {
        return { quadrant: data(btn, "area"), side: data(btn, "side") };
      });
    }
  };

  // app/javascript/components/viewer/ui_manager.js
  var UIManager = class {
    constructor() {
    }
    initialize(references) {
      this.references = references;
      this.analysis = this.references.analysis;
      this.simulator = this.references.simulator;
      this.simulator = this.references.simulator;
      this.implantCatalogManager = this.references.implantCatalogManager;
      this.simulationsManager = this.references.simulationsManager;
      this.lipofillingManager = this.references.lipofillingManager;
      this.faceAssessmentManager = this.references.faceAssessmentManager;
      this.viewer = this.references.viewer;
      this.mastopexyManager = this.references.mastopexyManager;
      this.messageManager = this.references.messageManager;
      this.cameraManager = this.references.cameraManager;
      this.openedMenu = null;
      this.openedAssessmentMenuWhenTransition = false;
      this.customEvents = {
        simulate: new Event("simulate"),
        resetBlendshapesUI: new Event("resetBlendshapesUI")
      };
      on(".checkbox-tool__info", "mouseover touchstart", () => removeClass(".side-menu__info-panel", "hide"));
      on(".checkbox-tool__info", "mouseout touchend", () => addClass(".side-menu__info-panel", "hide"));
    }
    initializeMainMenu() {
      this.setGridRowsMainMenu(1);
      on(".analysis-menu--face .side-menu__section-header", "click", (e3) => {
        this.manageSectionHeaderButton(e3.currentTarget);
      });
      on('.main-menu-js[data-simulation-type="mammo"] .side-menu__section-header', "click", (e3) => {
        this.selectMammoMainMenu(e3.currentTarget);
      });
      on('.main-menu-js[data-simulation-type="body"] .side-menu__section-header', "click", (e3) => {
        this.selectMammoMainMenu(e3.currentTarget);
      });
      on(".btn--open-main-menu, .btn--close-main-menu", "click", (event) => {
        const isOpen = hasClass(event.currentTarget, "btn--open-main-menu");
        toggleClass("body", "main-menu-open", isOpen);
        toggleClass(".main-menu-js, .implant-catalog__container", "hide", !isOpen);
        toggleClass(".btn--open-main-menu", "hide", isOpen);
        toggleClass(".joystick-wrapper--implant", "hidden", !isOpen);
        engine.render();
      });
      on(".side-menu__tabs--procedure .side-menu__tabs-item", "click", (e3) => {
        const target = e3.currentTarget;
        if (hasClass(target, "selected")) return;
        if (find(".side-menu__grid-container--procedure .side-menu__section-header.is-open-js"))
          this.selectMammoMainMenu(find(".side-menu__grid-container--procedure .side-menu__section-header.is-open-js"));
        removeClass(".side-menu__tabs--procedure .side-menu__tabs-item", "selected");
        addClass(target, "selected");
        addClass(".side-menu__grid-container--procedure", "hide");
        removeClass(`.side-menu__grid-container--procedure[data-tab="${data(target, "target")}"]`, "hide");
        this.references.skinManager.closeMenu();
        if (!this.viewer.isFace()) {
          find(".scars-section-js:not(.hide) .close-scars-menu-js")?.click();
          find(".lines-section-js:not(.hide) .close-lines-menu-js")?.click();
          find(".clone-skin-section-js:not(.hide) .close-clone-skin-js")?.click();
          find(".btn--toggle-shape-smoothing.selected")?.click();
          find(".btn--toggle-free-hand.selected")?.click();
        }
      });
      on(
        ".btn-comparison-js",
        "click",
        (e3) => this.references.comparisonManager.toggleComparison(e3)
      );
    }
    initializeSideMenu() {
      on(".close-side-menu-js", "click", () => addClass(".side-menu", "closed"));
      on(".open-side-menu-js", "click", () => removeClass(".side-menu", "closed"));
      on(".open-submenu-js, .close-submenu-js", "click", (event) => {
        const button = event.currentTarget;
        const target = data(button, "target");
        const targetElem = find(`.side-bar[data-submenu="${target}"], .submenu-js[data-submenu="${target}"]`);
        const section = data(button, "targetSection");
        const sectionElem = targetElem.querySelector(`[data-section="${section}"]`);
        const group = data(targetElem, "group");
        if (hasClass(targetElem, "hide") && hasClass(sectionElem, "hide")) {
          if (group && find(`.side-bar[data-group="${group}"]:not(.hide)`)) {
            const submenuToHide = find(`.side-bar[data-group="${group}"]:not(.hide)`);
            addClass(`.side-bar[data-group="${group}"]:not(.hide) .side-bar__section`, "hide");
            addClass(submenuToHide, "hide");
            removeClass(`.open-submenu-js[data-target="${data(submenuToHide, "submenu")}"]`, "selected");
          }
          removeClass(targetElem, "hide");
          removeClass(sectionElem, "hide");
          addClass(`.open-submenu-js[data-target="${target}"][data-target-section="${section}"]:not(.open-submenu-unselectable-js)`, "selected");
          addClass(`.open-submenu-js[data-target="${target}"][data-target-section="index"]:not(.open-submenu-unselectable-js)`, "selected");
        } else if (!hasClass(targetElem, "hide") && hasClass(sectionElem, "hide")) {
          addClass(`.side-bar[data-submenu="${target}"] .side-bar__section[data-section]`, "hide");
          removeClass(sectionElem, "hide");
          removeClass(`.open-submenu-js[data-target="${target}"]`, "selected");
          addClass(`.open-submenu-js[data-target="${target}"][data-target-section="${section}"]:not(.open-submenu-unselectable-js)`, "selected");
          addClass(`.open-submenu-js[data-target="${target}"][data-target-section="index"]:not(.open-submenu-unselectable-js)`, "selected");
          if (data(sectionElem, "section") !== "scars" && hasClass(".simulator", "simulator--scars")) {
            removeClass(".simulator", "simulator--scars");
            document.dispatchEvent(new Event("closeInstantTooltip-tooltip--rotate"));
            removeClass(".viewport-container--after-1 .btn--maximize", "disabled");
          }
        } else if (!hasClass(targetElem, "hide") && !hasClass(sectionElem, "hide")) {
          addClass(targetElem, "hide");
          addClass(`.side-bar[data-submenu="${target}"] .side-bar__section`, "hide");
          removeClass(`.open-submenu-js[data-target="${target}"]:not(.open-submenu-unselectable-js)`, "selected");
        }
        if (target === "analysis-menu" && hasClass(".btn--assessment", "selected") || target === "drawing-menu" && hasClass('button[data-target="drawing-menu"]', "selected") || target === "animations" && hasClass(".btn--5D", "selected") || target === "clothes" && hasClass(".btn--clothes", "selected"))
          this.turnOffWireframe();
        if (data(sectionElem, "section") !== "scars")
          find(".scars-section-js:not(.hide) .close-scars-menu-js")?.click();
        this.openedMenu = data(".side-bar.side-bar--right.not-main-menu:not(.hide)", "submenu") || null;
        if (this.openedMenu === null || !find(".simulator--loaded"))
          toggleActiveViewportListener(false);
        else
          this.selectViewport();
        if (!this.viewer.isFace()) toggleClass(".simulator", "simulator--assessment-open", hasClass(".btn--assessment", "selected"));
        find(".btn--toggle-shape-smoothing.selected")?.click();
        find(".btn--toggle-free-hand.selected")?.click();
        engine.render();
      });
    }
    turnOffWireframe() {
      removeClass(".simulator", "simulator--wireframe");
      engine.setWireframeParameters(void 0, { enable: false });
      removeClass(".btn--wireframe-js.selected", "selected");
    }
    initializeSelectedClass() {
      on(".selectable-js", "click", (event) => {
        const target = event.currentTarget;
        if (hasClass(".simulator", "comparison-opened")) find(".btn-comparison-js").click();
        const isSameButton = Array.from(findAll(".selectable-js.selected")).includes(target);
        const toolsOpenedClasses = Array.from(find(".simulator").classList).filter((klass) => klass.includes("tool-opened"));
        const tool = data(target, "tool");
        if (!hasClass(target, "procedure-button-js") && currentProcedure)
          find(`.procedure-button-js[data-target~="${currentProcedure}"]`).click();
        removeClass(".selectable-js", "selected");
        toggleClass(target, "selected", !isSameButton);
        toggleClass(data(target, "counterpart"), "selected", !isSameButton);
        removeClass(".simulator", toolsOpenedClasses);
        toggleClass(".simulator", `${tool}-tool-opened`, !isSameButton);
        hide(".tools-js");
        toggleClass(`.tool-panel--${data(target, "target")}`, "hide", isSameButton);
        engine.render();
        if (!isSameButton) dispatchEvent(new Event(`${tool}-opened`));
        else dispatchEvent(new Event(`${tool}-closed`));
      });
    }
    // TODO use as generic method to close tools and procedures. When opening something else
    // TODO only close when necessary (each close trigger 3ngine calls)
    // TODO probably needed a method to pause but not to close (ex. the user cannot draw while in transition)
    closeProceduresAndTools() {
      find(".clone-skin-section-js:not(.hide) .close-clone-skin-js")?.click();
      if (!this.viewer.isFace()) find(".side-menu__section-header.is-open-js")?.click();
      else find(`.side-menu__section-header[data-procedure=${this.references.faceMainMenuManager.selectedProcedure}]`)?.click();
      find(".open-lines-menu-js.selected") && find(".close-lines-menu-js").click();
      find(".btn--scars.selected") && find(".close-scars-menu-js").click();
      find(".btn--skin-treatment.selected") && find(".close-skin-menu-js").click();
      find(".toggle-custom-skin-js.selected")?.click();
      find(".btn--toggle-shape-smoothing.selected")?.click();
      find(".btn--toggle-free-hand.selected")?.click();
      addClass(".side-menu__injectables-section-js", "hide", hasClass(".side-menu__injectables-section-js", "hide"));
    }
    // TODO, for now not for face
    setGridRowsMainMenu(toolsRow) {
      if (this.viewer.isFace()) return;
      let rowOffset = 1;
      findAll(".side-menu__grid-container--procedure:not(.hide) .side-menu__grid-item:not(.side-menu-tools-js)").forEach((el, index2) => {
        el.style.setProperty("--grid-row", index2 + rowOffset);
        if (index2 + 1 == toolsRow) {
          find(".side-menu-tools-js")?.style.setProperty("--grid-row", index2 + rowOffset + 1);
          rowOffset = 2;
        }
      });
    }
    selectViewport() {
      const selectedViewport = find(".viewport-container.selected canvas");
      const showSelectedViewport = !!find(".simulator--loaded") && !find(`.simulator--multiple-viewports-1`) && !find(`.simulator--multiple-viewports-2`);
      if (!showSelectedViewport) return;
      toggleActiveViewportListener(true);
      onChangeActiveViewport({ currentTarget: selectedViewport || find("#afterCanvas1") });
    }
    // TODO rename as is used by body also
    selectMammoMainMenu(target) {
      const menu = find(`.main-menu-js[data-simulation-type="${this.viewer.isMammoOrFullbody() ? "mammo" : "body"}"]`);
      if (!!menu.querySelector(`.side-menu__section-header.is-open-js`) && !hasClass(target, "is-open-js")) {
        this.selectMammoMainMenu(menu.querySelector(".side-menu__section-header.is-open-js"));
      }
      this.setGridRowsMainMenu(data(target, "order"));
      if (this.viewer.isMammoOrFullbody()) this.implantCatalogManager.toggleContainer(false);
      removeClass(".mastopexy-tabs-js button", "selected");
      addClass('.mastopexy-tabs-js [data-target="mastopexy"]', "selected");
      this.references.linesManager.toggleLinesInactive();
      find(".toggle-custom-skin-js.selected")?.click();
      find(".btn--toggle-shape-smoothing.selected")?.click();
      find(".btn--toggle-free-hand.selected")?.click();
      this.manageSectionHeaderButton(target, { onOpen: () => {
        if (this.viewer.isMammoOrFullbody()) this.implantCatalogManager.setSectionName();
      } });
      if (find('.is-open-js[data-procedure="mastopexy"], .is-open-js[data-procedure="reduction"]')) {
        if (this.mastopexyManager.currentTechnique !== BreastIncisionType.NONE) {
          this.analysis.setAssesmentLines("both");
          removeClass(".joypad, .joypad-breast-tabs", "hide");
        }
      } else if (find(".lines-section-js:not(.hide)")) {
        this.references.linesManager.showLines(void 0);
      } else if (this.references.miaPreserveManager.procedureOpen()) {
        this.references.miaPreserveManager.initializeProcedure();
        if (this.references.miaPreserveManager.preserveProcedureOpen() && this.references.inputManager.getValue("breast_implant_mia_profile") === "extrahigh") {
          find("#breast_implant_mia_profile_extrahigh").checked = false;
          removeClass("#breast_implant_mia_profile_extrahigh", "was-checked");
        }
        toggleClass('.input-group--implant_mia-profile label[for="breast_implant_mia_profile_extrahigh"]', "hide", this.references.miaPreserveManager.preserveProcedureOpen());
      } else if (this.references.natrelleManager.procedureOpen()) {
        if (!this.simulator.isRound()) {
          find("#breast_implant_shape_rounded").checked = true;
          find("#breast_implant_shape_rounded").dispatchEvent(new Event("click"));
        }
      } else {
        this.analysis.hideAssesmentLines("both");
        addClass(".joypad, .joypad-breast-tabs", "hide");
      }
      if (this.viewer.isFullbody() && hasClass(target, "side-menu__section-header--breast-procedure") && hasClass(target, "is-open-js")) {
        this.cameraManager.fitCameraToArea("BREAST");
      } else if (this.viewer.isFullbody() && hasClass(target, "side-menu__section-header--breast-procedure") && !hasClass(target, "is-open-js")) {
        this.cameraManager.fitCameraToModel(1, true);
        this.cameraManager.focusCamera("NONE");
      }
      if (hasClass(target, "side-menu__section-header--feature-modifier") && hasClass(target, "is-open-js")) {
        this.references.featureModifiers.deselectFeature();
        this.references.featureModifiers.setProcedureEditor();
        this.references.simulator.fitCameraForProcedure();
        this.scrollToHeaderIfNeeded();
      } else if (hasClass(target, "side-menu__section-header--feature-modifier") && !hasClass(target, "is-open-js")) {
        this.cameraManager.fitCameraToModel(1, true);
        this.cameraManager.focusCamera("NONE");
      }
      this.showJoystick(parseInt(this.simulator.volumeSelected));
      toggleClass(".btn--viewer-feedback", "hide", find(".side-bar--right .side-menu__grid.open") || find(".side-bar--right .side-bar--main_menu:not(.hide)"));
      this.references.settingsManager.toggleMultisimDisabled();
    }
    // TODO Also used for face
    // this is used only for mammo procedures
    manageSectionHeaderButton(target, callbacks = () => {
    }) {
      const sideMenuSection = target.closest(".side-menu__section");
      const isMammoToolsSection = hasClass(sideMenuSection, "side-menu__section-mammo-js") || hasClass(sideMenuSection, "side-menu__section-body-js");
      if (isMammoToolsSection) return;
      const section = findParent(target, ".side-menu__section");
      const plus = target.querySelector(".icon_plus");
      const minus = target.querySelector(".icon_minus");
      const procedure = data(target, "procedure");
      if (hasClass(target, "is-open-js")) {
        show(plus);
        hide(minus);
        removeClass(section, "open");
        removeClass(".side-menu__section-header", "is-open-js");
        hide(".main-procedures-js");
        removeData(section, "open");
        if (callbacks.onClose) callbacks.onClose();
      } else {
        hide(".side-menu__section-header .icon_minus");
        show(".side-menu__section-header .icon_plus");
        show(minus);
        hide(plus);
        addClass(section, "open");
        data(section, "open", procedure);
        removeClass(".side-menu__section-header", "is-open-js");
        addClass(target, "is-open-js");
        hide(".main-procedures-js");
        if (procedure == "mastopexy") find('.mastopexy-tabs-js [data-target="mastopexy"]').click();
        show(`.${procedure}-js`);
        if (callbacks.onOpen) callbacks.onOpen();
      }
      if (this.viewer.isFace() && this.isDealingWithAssesmentSubmenu(procedure))
        this.faceAssessmentManager.changeOpenedMenu();
    }
    isDealingWithAssesmentSubmenu(procedure) {
      return ["proportions", "measurements", "heatmap", "analysis-skin-conditions"].includes(procedure);
    }
    onOpenMultipleSimulations(sims) {
      this.removeMultipleViewportClass();
      const nOfviewports = sims.length + (this.openedMenu === "analysis-menu" ? 1 : 0);
      addClass(".simulator", `simulator--multiple-viewports-${nOfviewports}`);
      if (sims.length > 1) {
        toggleActiveViewportListener(true);
        onChangeActiveViewport({ currentTarget: find("#afterCanvas1") });
      } else
        toggleActiveViewportListener(false);
      if (this.openedMenu === "drawing-menu") {
        find(".drawing-tools-js .selected")?.click();
        toggleClass(".delete-all-drawings-js", "disabled", engine.getDrawingCount("afterCanvas1") == 0);
      } else if (this.openedMenu === "analysis-menu")
        find(".analysis-mode-js button.selected").click();
    }
    update() {
      if (this.viewer.isMammoOrFullbody()) this.references.settingsManager.typeSettingsManager.enableCustomSimulation();
      if (hasClass(".simulator", "simulator--loaded")) {
        engine.render();
        if (!this.viewer.isFace()) return;
      }
      const activeSimulation = this.simulationsManager.active;
      const viewportContainerClassOrDefault = activeSimulation.viewportContainerClass || ".viewport-container--after-1";
      const activeCanvas = activeSimulation.canvasId || "afterCanvas1";
      this.toggleTools(activeSimulation.customId !== null && !activeSimulation.editable);
      let simulationObj;
      if (activeSimulation.customId) {
        if (this.simulationsManager.loadedSimulationsLength() > 1)
          simulationObj = this.simulationsManager.loadedSimulations[activeSimulation.canvasId];
        else
          simulationObj = this.simulationsManager.findActive();
        this.printViewportLabel(activeCanvas, simulationObj.name);
        this.viewportImplantLabel("");
        if (!activeSimulation.editable) {
          addClass(`${viewportContainerClassOrDefault} .btn--reset`, "disabled");
          addClass(`${viewportContainerClassOrDefault} .btn--save`, "disabled");
          removeClass(".btn--transition", "disabled");
          addClass(".simulator", "simulator--simulated");
          removeClass(".btn--new", "disabled");
          engine.render();
          return;
        }
      } else if (!hasClass(".simulator", "simulator--multisim")) {
        this.printViewportLabel("afterCanvas1", translations.after);
      }
      addClass(".btn--new", "disabled");
      if (this.viewer.isMammoOrFullbody()) {
        const breastVolume = +this.simulator.volumeSelected;
        this.showJoystick(breastVolume);
        toggleClass(".custom-simulator-js", "disabled", !(breastVolume > 0 || this.mastopexyManager.withChanges()));
        toggleClass(".disabled-if-no-procedure-no-volume", "disabled", breastVolume == 0 && !find(".surgery-technique :checked"));
        const showInfo = this.references.simulator.canvasWithChanges("afterCanvas1");
        toggleClass('.viewport-label[data-canvas="afterCanvas1"] .viewport-label__info', "hide", !showInfo);
      } else {
        const showInfo = simulationObj && this.simulationsManager.canShowInfo(simulationObj) || !simulationObj && this.simulator.canvasWithChanges(activeCanvas);
        toggleClass(`.viewport-label[data-canvas="${activeCanvas}"] .viewport-label__info`, "hide", !showInfo);
      }
      if (this.viewer.withChanges()) {
        removeClass(`${viewportContainerClassOrDefault} .btn--reset`, "disabled");
        removeClass(".btn--clone", "disabled");
        if (!this.simulationsManager.loadedSimFromOtherPatient()) {
          removeClass(".btn--transition", "disabled");
          data(".tool-label__transition", "tooltipText", translations.transition.transition);
        }
        addClass(".simulator", "simulator--simulated");
        const disable = !!activeSimulation.customId && !activeSimulation.changed;
        toggleClass(`${viewportContainerClassOrDefault} .btn--save`, "disabled", disable);
        toggleClass(`${viewportContainerClassOrDefault} .btn--reset`, "disabled", disable);
        if (this.viewer.isMammoOrFullbody()) {
          data("#afterCanvas1", "cc", this.simulator.volumeSelected);
          let html = "";
          if (this.simulator.asymmetry) {
            addClass(".viewport-label__text", "max-100");
            const rightHTML = this.simulator.getLabelSideHTML("right");
            const leftHTML = this.simulator.getLabelSideHTML("left");
            if (rightHTML) html = `${rightHTML} ${leftHTML}`;
          } else {
            if (this.implantCatalogManager.selected.right)
              html = this.implantCatalogManager.selected.right.reference;
          }
          this.viewportImplantLabel(html);
        }
      } else {
        const enableReset = activeSimulation.customId && activeSimulation.changed;
        addClass(".btn--clone", "disabled");
        toggleClass(`${viewportContainerClassOrDefault} .btn--reset`, "disabled", !enableReset);
        addClass(`${viewportContainerClassOrDefault} .btn--save`, "disabled");
        removeClass(".simulator", "simulator--simulated");
        if (this.viewer.isMammoOrFullbody()) {
          removeData("#afterCanvas1", "cc");
          this.viewportImplantLabel("");
        } else {
          dispatchEvent(this.customEvents.resetBlendshapesUI);
        }
      }
      this.editedProcedures();
      this.references.VRManager.update();
      toggleClass(".btn-comparison-js", "disabled", !this.viewer.withChanges() && this.viewer.isFace() && !hasClass(".simulator", "simulator--loaded"));
      engine.render();
    }
    toggleTools(hide2) {
      toggleClass(".blendshape-tools", "hide", hide2);
      toggleClass(".procedure-button-js", "hide", hide2);
      toggleClass(".breast-button-js", "hide", hide2);
      if (hide2) {
        currentProcedure = "";
        const openedTools = Array.from(find(".simulator").classList).filter((klass) => klass.includes("tool-opened"));
        removeClass(".procedure-button-js", "selected");
        removeClass(".blendshapebutton-js", "selected");
        removeClass(".breast-button-js", "selected");
        removeClass(".simulator", openedTools);
        addClass(".slider-value", "invisible");
        addClass(".tool-panel", "hide");
        addClass(".tools-js", "hide");
      }
    }
    viewportImplantLabel(text2 = "") {
      if (find(".simulator--loaded")) text2 === "";
      for (const elem2 of findAll(".viewport-label__implant")) insertHTML(elem2, text2);
      toggleClass(".viewport-label__implant", "hide", text2 === "");
    }
    showJoystick(volumeSelected) {
      this.showImplatJoystick(volumeSelected);
      this.showLinesJoystick();
    }
    showImplatJoystick(volumeSelected) {
      const sectionAugmentation = ["primary-augmentation", "revision", "mastopexy", "mia", "preserve", "natrelle"].includes(data(".main-menu-js .side-menu__section.side-menu__grid.open", "open"));
      const volume = volumeSelected > 0;
      toggleClass(".joystick-wrapper--implant", "hide", !(sectionAugmentation && volume));
    }
    showLinesJoystick() {
      const linesSelected = this.references.linesManager.selectedLine;
      toggleClass(".joystick-wrapper--lines", "hide", !linesSelected);
      toggleClass(findParent(".lines__lock-view", ".lines__buttons"), "hide-breakpoint-lg", linesSelected);
    }
    removeMultipleViewportClass() {
      const simulator2 = find(".simulator");
      simulator2.className = simulator2.className.replace(/simulator--multiple-viewports-\d+/, "").trim();
    }
    toggleSaveModalWithDontSave(enable) {
      toggleClass(".modal__step--save__unsaved-simulation", "hide", !enable);
      if (enable) {
        const name51 = simulations.find(({ custom_id }) => custom_id === this.simulationsManager.active.customId).name;
        const text2 = translations.saveSingleSimulationParagraph.replace("PLACEHOLDER", name51);
        find(".unsaved-simulation-paragraph").innerText = text2;
      }
      addClass(".buttons-save-js", "hide");
      removeClass(enable ? ".buttons-with-dont-save-js" : ".default-save-buttons-js", "hide");
    }
    hideZoomWindowClickHandler = (e3) => {
      const isElementZoom = hasClass(e3.target, "zoom-range-input") || hasClass(e3.target, "zoom-js") || hasClass(e3.target, "icon_zoom") || e3.target.parentElement.querySelector(".icon_zoom") || hasClass(e3.target.parentElement, "icon_zoom");
      if (isElementZoom) return;
      addClass(".zoom-slider", "hide");
      removeClass(".zoom-js", "selected");
      window.removeEventListener("click", this.hideZoomWindowClickHandler);
    };
    printViewportLabel(canvas, text2) {
      const viewportLabels = [...findAll(`.viewport-label[data-canvas="${canvas}"] .viewport-label__text`)];
      viewportLabels.forEach((label) => insertHTML(label, text2));
    }
    // Lines only set edited in tools
    // Only for breast, body and fullbody (TODO for face)
    // TODO also for custom simulation and catalog?
    editedProcedures() {
      const simulatedCanvas = this.references.simulator.simulatedCanvas["afterCanvas1"];
      if (!simulatedCanvas) return;
      const tools = ["scars", "clone-skin", "shape-smoothing", "free-hand"];
      removeClass(".btn--drawing", "edited");
      removeClass(".side-menu__section-header", "edited");
      if (!!simulatedCanvas.face) {
        for (let procedure of Object.keys(simulatedCanvas.face)) {
          if (!simulatedCanvas.face[procedure]) continue;
          if (procedure == "nose_catalog") procedure = "rhinoplasty";
          if (procedure == "lips_catalog") procedure = "lip_augmentation";
          if (procedure == "eyelids_catalog") procedure = "eyelids";
          addClass(`.side-menu__procedure-header-js[data-procedure="${procedure}"]`, "edited");
        }
        toggleClass(".side-menu__section-header--implantech", "edited", this.references.implantechManager.withChanges());
      }
      if (!!simulatedCanvas.body) {
        for (const procedure of Object.keys(simulatedCanvas.body)) {
          addClass(`.side-menu__section-header--feature-modifier[data-procedure="${procedure}"]`, "edited");
        }
      }
      if (!!simulatedCanvas.lines && simulatedCanvas.lines.length > 0) {
        addClass('.side-menu__grid-container--procedure[data-tab="tools"] .side-menu__section-header[data-target-section="lines"]', "edited");
        for (const procedure of simulatedCanvas.lines) {
          if (procedure != "lines") addClass(`.side-menu__section-header--feature-modifier[data-procedure="${procedure}"]`, "edited");
        }
      }
      if (!!simulatedCanvas.skin && simulatedCanvas.skin.length > 0) {
        addClass('.side-menu__grid-container--procedure[data-tab="tools"] .side-menu__section-header[data-target-section="skin"]', "edited");
        for (const procedure of simulatedCanvas.skin) {
          if (!["skin", "custom-skin"].includes(procedure)) addClass(`.side-menu__section-header--feature-modifier[data-procedure="${procedure}"]`, "edited");
        }
      }
      for (const tool of tools) {
        if (simulatedCanvas[tool]) {
          addClass(`.side-menu__grid-container--procedure[data-tab="tools"] .side-menu__section-header[data-target-section="${tool}"]`, "edited");
        }
      }
      if (!!simulatedCanvas.drawing) {
        addClass(".btn--drawing", "edited");
      }
      if (!this.viewer.isMammoOrFullbody()) return;
      const volumeChange = !!(simulatedCanvas?.right?.volume || simulatedCanvas?.left?.volume);
      if (volumeChange && simulatedCanvas.augmentationProcedure) {
        addClass(`.side-menu__section-header[data-procedure="${simulatedCanvas.augmentationProcedure}"]`, "edited");
      }
      if (this.mastopexyManager.withChanges(false) && simulatedCanvas.mastopexyProcedure) {
        addClass(`.side-menu__section-header[data-procedure="${simulatedCanvas.mastopexyProcedure}"]`, "edited");
      }
      if (this.mastopexyManager.reductionWithChanges() && simulatedCanvas.reductionProcedure) {
        addClass(`.side-menu__section-header[data-procedure="${simulatedCanvas.reductionProcedure}"]`, "edited");
      }
      if (this.references.lipofillingManager.withChanges() && simulatedCanvas.lipofillingProcedure) {
        addClass(`.side-menu__section-header[data-procedure="${simulatedCanvas.lipofillingProcedure}"]`, "edited");
      }
    }
    scrollToHeaderIfNeeded() {
      const target = find(".side-menu__section-header.is-open-js");
      const procedure = data(".side-menu__section-header.is-open-js", "procedure");
      const lastElement = [...findAll(`.${procedure}-js`)].pop();
      if (!lastElement) return;
      const lastElementRect = lastElement.getBoundingClientRect();
      const parentElement = find('.side-menu__grid-container--procedure[data-tab="procedures"]');
      const parentElementRect = parentElement.getBoundingClientRect();
      const offset = lastElementRect.bottom - parentElementRect.bottom;
      if (offset > 0) {
        try {
          target.scrollIntoView({ behavior: "smooth", block: "start" });
        } catch (e3) {
          target.scrollIntoView();
        }
      }
    }
  };

