  // app/javascript/components/viewer/face/eyelids_manager.js
  var EyelidsManager = class {
    constructor() {
    }
    initialize(references) {
      this.references = references;
      this.simulationsManager = references.simulationsManager;
      this.messageManager = references.messageManager;
      this.UIManager = references.UIManager;
      this.customSkinManager = references.customSkinManager;
      this.simulationsManager = references.simulationsManager;
      this.cameraManager = references.cameraManager;
      this.checkAssetsInterval;
      this.selectedUpperEyelid;
      this.eyelidsUnderEyeSkin();
      this.setUpperEyelid();
      this.manageInputUpperEyelidIntensity();
      this.resetUpperEyelid();
      this.onAutomaticLift();
      on(".btn--cancel-processing-eyelids", "click", () => this.processCancelled = true);
    }
    setIntervalAssets(options2) {
      if (options2.eyelidMaskJsonUrl)
        this.loadEyelids();
      else
        this.checkAssetsInterval = setInterval(this.checkAssets.bind(this), 2e3);
    }
    async checkAssets() {
      const assets = JSON.parse(await Ajax.get(viewerRoutes.checkAssets));
      if (!!assets.eyelidMaskJsonUrl) {
        clearInterval(this.checkAssetsInterval);
        options.eyelidMaskJsonUrl = assets.eyelidMaskJsonUrl;
        options.eyelidTextureUrls = assets.eyelidTextureUrls;
        this.loadEyelids();
      }
    }
    onAutomaticLift() {
      on("#eyelid-automatic-lift", "change", (e3) => {
        this.liftEyelidLineDeformation(e3.currentTarget.checked ? 0.1 : 0);
        this.setSimulatedCanvas();
      });
    }
    liftEyelidLineDeformation(intensity) {
      engine.liftEyelidLineDeformation("afterCanvas1", intensity, { left: true, right: true });
      engine.simulate("afterCanvas1");
    }
    withChanges() {
      const upperEyelidWithChanges = !!find("input[name=eyelid]:checked") && +find("#upper-eyelids-intensity-range").value > 0;
      const withChanges = +find("#skin-eyelids-undereye").value > 0 || upperEyelidWithChanges;
      return withChanges;
    }
    reset() {
      find("input[name=eyelid]:checked")?.click();
      find(".btn--reset-skin-eyelids-undereye:not(.disabled)")?.click();
      this.setSimulatedCanvas();
      this.UIManager.update();
    }
    eyelidsUnderEyeSkin() {
      on("#skin-eyelids-undereye", "input", (e3) => {
        [SkinImperfectionType.WRINKLE_EYEBAGS, SkinImperfectionType.WRINKLE_TEAR_TROUGHS].forEach((type2) => {
          const intensity = e3.currentTarget.value / 100;
          const cleaning = { left: { intensity }, right: { intensity } };
          toggleClass(".btn--reset-skin-eyelids-undereye", "disabled", intensity === 0);
          engine.setInpaintingParameters("afterCanvas1", { skinImperfections: [{ type: type2, cleaning }] });
        });
        if (this.simulationsManager.active.customId) this.simulationsManager.active.changed = true;
        this.setSimulatedCanvas();
        this.UIManager.update();
      });
      on(".btn--reset-skin-eyelids-undereye", "click", (event) => {
        [SkinImperfectionType.WRINKLE_EYEBAGS, SkinImperfectionType.WRINKLE_TEAR_TROUGHS].forEach((type2) => {
          const cleaning = { left: { intensity: 0 }, right: { intensity: 0 } };
          engine.setInpaintingParameters("afterCanvas1", { skinImperfections: [{ type: type2, cleaning }] });
          addClass(event.currentTarget, "disabled");
          resetSlider("skin-eyelids-undereye", 0);
          find("#skin-eyelids-undereye").value = 0;
        });
        this.setSimulatedCanvas();
      });
    }
    loadEyelids() {
      const eyelids = {};
      let it2 = 1;
      for (const eyelidTexture of options.eyelidTextureUrls) {
        const id = `eyelid${it2}`;
        eyelids[id] = eyelidTexture;
        it2++;
      }
      engine.loadEyelids(options.eyelidMaskJsonUrl, eyelids).then(() => {
        addClass(".eyelids-loading", "hide");
        removeClass(".eyelids-loaded", "hide");
      });
    }
    withTextureChanges() {
      return !!find("input[name=eyelid]:checked") && +find("#upper-eyelids-intensity-range").value > 0;
    }
    setUpperEyelid() {
      on("input[name=eyelid]", "click", (e3) => {
        const target = e3.currentTarget;
        if (this.selectedUpperEyelid == target.value) {
          this.setUpperEyelidIntensity(0);
          this.liftEyelidLineDeformation(0);
          target.checked = false;
          this.selectedUpperEyelid = null;
          addClass(".upper-eyelids-intensity", "disabled");
          addClass(".eyelid-automatic-lift-container", "disabled");
          this.setSimulatedCanvas();
          this.UIManager.update();
          return;
        }
        if (this.simulationsManager.active.customId) this.simulationsManager.active.changed = true;
        this.liftEyelidLineDeformation(find("#eyelid-automatic-lift").checked ? 0.1 : 0);
        removeClass(".eyelid-automatic-lift-container", "disabled");
        removeClass(".upper-eyelids-intensity", "disabled");
        this.selectedUpperEyelid = target.value;
        this.setUpperEyelidIntensity(0.8);
        resetSlider("upper-eyelids-intensity-range", 0.8);
        this.setSimulatedCanvas();
        this.UIManager.update();
      });
    }
    resetUpperEyelid() {
      on(".btn--reset-eyelids-upper", "click", () => {
        resetSlider("upper-eyelids-intensity-range", 0.8);
        this.setUpperEyelidIntensity(0.8);
        this.setSimulatedCanvas();
      });
    }
    setUpperEyelidIntensity(intensity) {
      intensity = parseFloat(intensity);
      window.intensity = intensity;
      toggleClass(".btn--reset-eyelids-upper", "disabled", intensity === 0.8);
      engine.showBlepharoplasty("afterCanvas1", this.selectedUpperEyelid, {
        left: intensity,
        right: intensity
      });
      if (this.simulationsManager.active.customId) this.simulationsManager.active.changed = true;
      this.setSimulatedCanvas();
      this.UIManager.update();
    }
    manageInputUpperEyelidIntensity() {
      on("#upper-eyelids-intensity-range", "input", (e3) => {
        this.setUpperEyelidIntensity(e3.currentTarget.value);
        this.setSimulatedCanvas();
      });
    }
    open() {
      this.originalZoom = engine.getCameraZoom();
      this.cameraManager.fitCameraToModel(1.7, false);
    }
    close() {
      find(".toggle-custom-skin-js.selected")?.click();
      hide(".skin-floating-menu");
      this.cameraManager.setZoom(this.originalZoom, true);
    }
    // Use eyelids_catalog as there are also eyelids feature modifiers 
    // Catalog may not be the best naming but for coherence with lips and nose, we will keep it for now
    // The best solution IMO is to rename eyelids feature modifiers to brows but it will require too many changes for now 
    setSimulatedCanvas() {
      const { simulatedCanvas } = this.references.simulator;
      const canvas = simulatedCanvas.afterCanvas1 ??= {};
      const face3 = canvas.face ??= {};
      face3.eyelids_catalog = this.withChanges();
    }
  };

  // app/javascript/components/viewer/clone_skin_manager.js
  var CloneSkinManager = class {
    constructor() {
    }
    initialize(references) {
      this.references = references;
      this.viewer = this.references.viewer;
      this.simulationsManager = this.references.simulationsManager;
      this.canvas = "afterCanvas1";
      this.touch = !window.matchMedia("(hover: hover)").matches;
      this.state = "off";
      on(".btn--clone-skin", "click", () => {
        find(".autorotation-js.selected")?.click();
        engine.toggleStampTool(true, this.canvas);
        engine.setStampParameters(this.canvas, { range: find("#clone-skin-area").value });
        this.startCopying();
        addClass(".simulator", "simulator--clone-skin");
      });
      on(".close-clone-skin-js", "click", () => {
        engine.toggleStampTool(false, this.canvas);
        addClass(".btn--clone-skin-new", "disabled");
        removeClass(findParent("#clone-skin-area", ".side-menu__section-slider-tool"), "disabled");
        removeClass(".simulator", "simulator--clone-skin");
        this.state = "off";
      });
      on(engine, StampEvent.Type.COPY, () => {
        this.startPasting();
      });
      on(engine, StampEvent.Type.PASTE, () => {
        if (this.simulationsManager.active.customId)
          this.simulationsManager.active.changed = true;
        this.updateUI();
      });
      on(engine, StampEvent.Type.SELECT, () => {
        if (this.state === "copying") {
          this.state = "copyingSelected";
          removeClass(".btn--clone-skin-copy", "disabled");
        } else if (this.state === "pasting") {
          this.state = "pastingSelected";
          removeClass(".btn--clone-skin-paste", "disabled");
        }
      });
      on(engine, StampEvent.Type.DESELECT, () => {
        if (this.state === "copyingSelected") {
          this.startCopying();
        } else if (this.state === "pastingSelected") {
          this.startPasting();
        }
      });
      on(".clone-skin__undo", "click", () => {
        engine.undoStampAction(this.canvas);
        if (this.simulationsManager.active.customId)
          this.simulationsManager.active.changed = true;
        this.updateUI();
      });
      on(".clone-skin__redo", "click", () => {
        engine.redoStampAction(this.canvas);
        if (this.simulationsManager.active.customId)
          this.simulationsManager.active.changed = true;
        this.updateUI();
      });
      on(".delete-all-clone-skin-js", "click", () => {
        this.references.modalManager.open("reset-clone-skin");
      });
      on(".modal-reset-clone-skin-js", "click", () => {
        this.reset();
        this.references.modalManager.close();
      });
      on(".btn--clone-skin-new", "click", () => {
        this.startCopying();
      });
      on("#clone-skin-area", "input change", (e3) => {
        engine.setStampParameters(this.canvas, { range: e3.currentTarget.value });
      });
      on("#clone-skin-flip", "change", (e3) => {
        engine.toggleStampFlip(e3.currentTarget.checked);
      });
      on(".btn--clone-skin-copy", "click", () => {
        engine.copyStampManually(this.canvas);
      });
      on(".btn--clone-skin-paste", "click", () => {
        engine.pasteStampManually(this.canvas);
      });
    }
    updateUI() {
      toggleClass(".clone-skin__undo", "disabled", !engine.canUndoStampAction(this.canvas));
      toggleClass(".clone-skin__redo", "disabled", !engine.canRedoStampAction(this.canvas));
      toggleClass(".delete-all-clone-skin-js", "disabled", !(engine.getStampCount(this.canvas) > 0));
      this.references.simulator.simulatedCanvas[this.canvas]["clone-skin"] = engine.getStampCount(this.canvas) > 0;
      if (this.viewer.isMammo()) this.references.simulator.setExportParams("afterCanvas1");
      this.references.UIManager.update();
    }
    withChanges() {
      return engine.getStampCount(this.canvas) > 0;
    }
    reset(simulate = true) {
      if (this.withChanges() && this.simulationsManager.active.customId) {
        this.simulationsManager.active.changed = true;
      }
      if (simulate) engine.clearStamps(this.canvas);
      this.updateUI();
    }
    startCopying() {
      this.state = "copying";
      engine.enableStampCopy();
      addClass(".btn--clone-skin-new", "disabled");
      removeClass(findParent("#clone-skin-area", ".side-menu__section-slider-tool"), "disabled");
      insertHTML(".tooltip--clone-skin", this.touch ? translations.cloneSkin.copyTouch : translations.cloneSkin.copy);
      addClass(".btn--clone-skin-copy", "disabled");
      removeClass(".btn--clone-skin-copy", "hide");
      addClass(".btn--clone-skin-paste", "hide");
    }
    startPasting() {
      this.updateUI();
      this.state = "pasting";
      removeClass(".btn--clone-skin-new", "disabled");
      addClass(findParent("#clone-skin-area", ".side-menu__section-slider-tool"), "disabled");
      insertHTML(".tooltip--clone-skin", this.touch ? translations.cloneSkin.pasteTouch : translations.cloneSkin.paste);
      addClass(".btn--clone-skin-copy", "disabled");
      addClass(".btn--clone-skin-copy", "hide");
      removeClass(".btn--clone-skin-paste", "hide");
      addClass(".btn--clone-skin-paste", "disabled");
    }
  };

  // app/javascript/components/viewer/custom_skin_manager.js
  var CustomSkinManager = class {
    constructor() {
    }
    initialize(references) {
      this.references = references;
      this.simulationsManager = references.simulationsManager;
      this.viewer = references.viewer;
      this.UIManager = references.UIManager;
      this.messageManager = references.messageManager;
      this.skinManager = references.skinManager;
      this.modalManager = references.modalManager;
      this.settingsManager = references.settingsManager;
      this.warmedUp = false;
      this.pressingShiftKeyHandler = this.pressingShiftKey.bind(this);
      this.releasingShiftKeyHandler = this.releasingShiftKey.bind(this);
      this.customTreatments = 0;
      this.tooltipClickCustomShown = false;
      this.tooltipCustomAreaShown = viewerSettings.extra_attributes.custom_area_shown || 0;
      this.manageSkinCustom();
      this.rotateButton();
    }
    manageSkinCustom() {
      if (!this.viewer.isFace()) {
        on(".toggle-custom-skin-js", "click", (event) => {
          if (hasClass(event.currentTarget, "selected")) this.onUnselect();
          else this.onStart();
          toggleClass(".toggle-custom-skin-js", "selected");
          engine.toggleCustomRegionTreatment("afterCanvas1", !!find(".toggle-custom-skin-js.selected"));
        });
        this.observerMenu();
      }
      on(engine, CustomRegionTreatmentEvent.Type.START, () => {
        document.dispatchEvent(new Event(`closeInstantTooltip-tooltip--custom-skin`));
        document.drawingCustom = true;
      });
      on(engine, CustomRegionTreatmentEvent.Type.END, async (event) => this.cleanModel(event));
      on("#treatment-custom-intensity, #treatment-custom-intensity-text", "input", (event) => {
        let value = event.currentTarget.value;
        if (value == "") value = 1;
        value = parseInt(value);
        engine.setCustomRegionTreatmentInterpolation("afterCanvas1", value / 100);
      });
      on("#treatment-custom-intensity-text", "blur", (event) => {
        if (event.currentTarget.value == "") {
          event.currentTarget.value = 1;
          resetSlider("treatment-custom-intensity", 0);
        }
      });
      on(".apply-custom-skin-js", "click", () => {
        engine.applyCustomRegionTreatment("afterCanvas1");
        show(".with-skin-custom-js, .skin-rotate-block-js, .delete-all-custom-skin-container");
        this.customTreatments++;
        addClass(".manage-custom-treatment", "disabled");
        removeClass(".custom-skin-thickness__container", "disabled");
        removeClass(".skin-limit-setting-js, .delete-all-custom-skin-container", "disabled");
        addClass(".btn--skin-treatment", "edited");
        addClass('button[data-mode="CUSTOM"]', "btn--edited");
        const procedure = this.viewer.isBody() ? this.references.featureModifiers.selectedProcedure() || "custom-skin" : "custom-skin";
        this.updateSimulatedCanvas(procedure);
        if (this.viewer.isMammo()) this.references.simulator.setExportParams("afterCanvas1");
        this.UIManager.update();
      });
      on(".cancel-custom-skin-js", "click", () => this.cancelCustomSkin());
      on("#tool-skin-show-custom, #procedure-skin-show-custom", "click", (event) => {
        const checked = event.currentTarget.checked;
        find("#tool-skin-show-custom").checked = checked;
        find("#procedure-skin-show-custom").checked = checked;
        engine.highlightCustomRegionTreatments("afterCanvas1", checked);
      });
      on(".delete-all-custom-skin", "click", () => this.modalManager.open("clear-custom-skin"));
      on(".modal-clear-custom-js", "click", (event) => {
        this.modalManager.close();
        this.reset();
        this.messageManager.snackbar(translations.customAreasDeleted);
      });
      on(".btn--custom-skin-tool", "click", (event) => {
        if (hasClass(event.currentTarget, "selected")) return;
        if (!hasClass(".manage-custom-treatment", "disabled")) {
          this.cancelCustomSkin();
        }
        const tool = data(event.currentTarget, "tool");
        removeClass(".btn--custom-skin-tool", "selected");
        addClass(`.btn--custom-skin-tool[data-tool="${tool}"]`, "selected");
        toggleClass(".custom-skin-thickness__container", "hide", tool == "area");
        toggleClass(".custom-skin-thickness__container", "disabled", tool == "area");
        engine.setCustomRegionTreatmentDrawMode("afterCanvas1", CustomRegionTreatmentDrawMode[tool.toUpperCase()]);
        this.showWhiteTooltip();
      });
      this.initializeThicknessSlider();
    }
    cancelCustomSkin() {
      show(".skin-rotate-block-js");
      engine.cancelCustomRegionTreatment("afterCanvas1");
      if (this.customTreatments > 0) removeClass(".delete-all-custom-skin-container", "disabled");
      this.updateSimulatedCanvas();
      addClass(".manage-custom-treatment", "disabled");
      removeClass(".custom-skin-thickness__container", "disabled");
      removeClass(".skin-limit-setting-js", "disabled");
    }
    reset(simulate = true) {
      if (this.customTreatments == 0) return;
      this.removeCustomTreatments(simulate);
      removeClass('button[data-mode="CUSTOM"]', "btn--edited");
      if (!this.viewer.isFace())
        removeClass(".btn--skin-treatment", "edited");
      else
        toggleClass(".btn--skin-treatment", "edited", this.skinManager.modifiedRegions.length > 0 || find("#treatment-intensity").value > 0);
      this.UIManager.update();
    }
    async cleanModel(event) {
      document.drawingCustom = false;
      if (event.rle == null) {
        this.messageManager.snackbar(translations.drawCustomLargerArea, { extraClasses: "snackbar--error" });
        return;
      }
      toggleLoader("custom-skin");
      if (isDemo()) {
        this.afterCustomCleaningReceived("/cases/face1/tmp/face/wrinkle_inpainting/texture.jpg");
        return;
      }
      fetch(viewerRoutes.skinCustomCleaning, {
        method: "POST",
        headers: {
          "Content-Type": "application/json"
        },
        body: JSON.stringify({
          rle: event.rle,
          authenticity_token: attr('meta[name="csrf-token"]', "content")
        })
      }).then((response) => {
        if (!response.ok)
          this.messageManager.snackbar(translations.error, { extraClasses: "snackbar--error" });
        return response.blob();
      }).then((blob) => {
        this.afterCustomCleaningReceived(URL.createObjectURL(blob));
      });
    }
    removeCustomTreatments(simulate = true) {
      this.customTreatments = 0;
      this.updateSimulatedCanvas();
      if (simulate) engine.deleteAllCustomRegionTreatments("afterCanvas1");
      hide(".with-skin-custom-js, .delete-all-custom-skin-container");
      addClass(".delete-all-custom-skin-container", "disabled");
    }
    afterCustomCleaningReceived(src) {
      toggleLoader("custom-skin");
      this.simulationsManager.active.changed = true;
      const max3 = +find("#treatment-custom-intensity").max;
      resetSlider("treatment-custom-intensity", max3);
      find("#treatment-custom-intensity-text").value = max3;
      hide(".skin-rotate-block-js");
      removeClass(".manage-custom-treatment", "disabled");
      addClass(".custom-skin-thickness__container", "disabled");
      addClass(".skin-limit-setting-js, .delete-all-custom-skin-container", "disabled");
      find(".scroll-custom-js")?.scrollIntoView({ behavior: "smooth", block: "start" });
      let image2 = new Image();
      image2.onload = () => {
        engine.setCustomRegionTreatment("afterCanvas1", image2);
        image2.src = "";
        image2 = null;
      };
      image2.src = src;
      this.UIManager.update();
    }
    withChanges() {
      return this.customTreatments > 0;
    }
    closeMenu() {
      document.removeEventListener("keydown", this.pressingShiftKeyHandler);
      document.removeEventListener("keyup", this.releasingShiftKeyHandler);
      document.dispatchEvent(new Event(`closeInstantTooltip-tooltip--custom-skin`));
      find(".skin-rotate-js.selected")?.click();
      find(".tooltip--click-custom-skin")?.remove();
      hide(".skin-floating-menu");
      engine.cancelCustomRegionTreatment("afterCanvas1");
      engine.toggleCustomRegionTreatment("afterCanvas1", false);
      addClass(".manage-custom-treatment", "disabled");
    }
    // TODO, remove observer (right now it works because the eddited class added to the button)
    observerMenu() {
      const observer = new MutationObserver((mutationsList) => {
        if (!observerModifiedClassList(mutationsList)) return;
        const mainProcedureOpen = !!find(".btn--skin-treatment.selected");
        const featureModifierOpen = !!find(".side-menu__section-header--feature-modifier.is-open-js");
        if (!(mainProcedureOpen || featureModifierOpen)) this.closeMenu();
        else {
          if (!this.tooltipClickCustomShown && !viewerSettings.extra_attributes.click_custom_skin_tooltip_shown && this.viewer.isMammo()) {
            this.settingsManager.updateViewerSettings({ viewer_settings: { click_custom_skin_tooltip_shown: true } });
            this.tooltipClickCustomShown = true;
            this.messageManager.bodyTooltip(
              translations.clickCustomSkinTooltip,
              find(".toggle-custom-skin-js"),
              "left",
              "tooltip--click-custom-skin tooltip-label--white",
              { seconds: 3600, id: "tooltip--click-custom-skin" }
            );
          }
          show(".skin-floating-menu");
          if (!!find(".toggle-custom-skin-js.selected")) {
            document.addEventListener("keydown", this.pressingShiftKeyHandler);
            document.addEventListener("keyup", this.releasingShiftKeyHandler);
          }
          engine.toggleCustomRegionTreatment("afterCanvas1", !!find(".toggle-custom-skin-js.selected"));
        }
      });
      observer.observe(find(".btn--skin-treatment"), { attributes: true, attributeFilter: ["class"], attributeOldValue: true });
    }
    skinCustomCleaningWarmup() {
      fetch(viewerRoutes.skinCustomCleaning, {
        method: "POST",
        headers: {
          "Content-Type": "application/json"
        },
        body: JSON.stringify({
          rle: [],
          authenticity_token: attr('meta[name="csrf-token"]', "content")
        })
      });
      this.warmedUp = true;
    }
    onStart() {
      if (!this.warmedUp && !isDemo()) this.skinCustomCleaningWarmup();
      const drawMode = data(".btn--custom-skin-tool.selected", "tool");
      const thickness = find("#tool-custom-skin-thickness").value / 100;
      toggleClass(".custom-skin-thickness__container", "hide", drawMode == "area");
      removeClass(".custom-skin-thickness__container", "disabled");
      engine.setCustomRegionTreatmentDrawMode("afterCanvas1", CustomRegionTreatmentDrawMode[drawMode.toUpperCase()]);
      engine.setCustomRegionTreatmentBrushSize("afterCanvas1", thickness);
      find(".side-menu__grid-container--procedure[data-tab='procedures'] .btn-show-lines.active")?.click();
      show(".skin-rotate-block-js, .skin-floating-menu");
      removeClass(".btn--custom-skin-tool", "disabled");
      document.addEventListener("keydown", this.pressingShiftKeyHandler);
      document.addEventListener("keyup", this.releasingShiftKeyHandler);
      this.showWhiteTooltip();
    }
    onUnselect() {
      document.dispatchEvent(new Event(`closeInstantTooltip-tooltip--custom-skin`));
      find(".skin-rotate-js.selected")?.click();
      addClass(".btn--custom-skin-tool", "disabled");
      addClass(".custom-skin-thickness__container", "disabled");
      addClass(".custom-skin-thickness__container", "hide");
      document.removeEventListener("keydown", this.pressingShiftKeyHandler);
      document.removeEventListener("keyup", this.releasingShiftKeyHandler);
      if (!find(".manage-custom-treatment.disabled")) this.cancelCustomSkin();
      hide(".skin-rotate-block-js");
    }
    pressingShiftKey(event) {
      const otherKeyPressed = event.metaKey || event.ctrlKey || event.altKey;
      if (event.shiftKey && !document.drawingCustom && !otherKeyPressed && !!find(".manage-custom-treatment.disabled")) {
        engine.toggleCustomRegionTreatment("afterCanvas1", false);
        document.pressingShift = true;
        document.dispatchEvent(new Event(`closeInstantTooltip-tooltip--custom-skin`));
      } else {
        this.onShiftReleased();
      }
    }
    onShiftReleased() {
      document.pressingShift = false;
      if (!!find(".skin-rotate-js.selected")) return;
      engine.toggleCustomRegionTreatment("afterCanvas1", true);
    }
    releasingShiftKey() {
      if (document.pressingShift) this.onShiftReleased();
    }
    rotateButton() {
      const button = ".skin-rotate-js";
      on(button, "click", () => {
        toggleClass(button, "selected");
        const isSelected = hasClass(button, "selected");
        engine.toggleCustomRegionTreatment("afterCanvas1", !isSelected);
      });
    }
    initializeThicknessSlider() {
      this.toolThicknessPreview = new SliderWithLinePreview({
        name: "tool-custom-skin-thickness",
        color: "#fff",
        container: ".line-preview__container--custom-skin",
        onChange: (value, preview) => {
          this.updatePreview(value, preview, "tool");
          const thickness = value / 100;
          engine.setCustomRegionTreatmentBrushSize("afterCanvas1", thickness);
        }
      }).initialize();
      this.procedureThicknessPreview = new SliderWithLinePreview({
        name: "procedure-custom-skin-thickness",
        color: "#fff",
        container: ".line-preview__container--custom-skin",
        onChange: (value, preview) => {
          this.updatePreview(value, preview, "procedure");
          const thickness = value / 100;
          engine.setCustomRegionTreatmentBrushSize("afterCanvas1", thickness);
        }
      }).initialize();
    }
    updatePreview(value, preview, menuId) {
      const top = find(`#${menuId}-custom-skin-thickness`).getBoundingClientRect().top;
      const size2 = 0.375 + Math.min(parseInt(value), 100) / 100;
      find(".line-preview__container--custom-skin").style.top = `${top - 64 - 52 + 18}px`;
      preview.setWidth(`${size2 * 4}em`);
      preview.setHeight(`${size2 * 4}em`);
      preview.setBorderRadius("100%");
      const percentage = find(`#${menuId}-custom-skin-thickness`).style.getPropertyValue("--percentage");
      const otherMenuId = menuId === "tool" ? "procedure" : "tool";
      find(`#${otherMenuId}-custom-skin-thickness`).value = value;
      find(`#${otherMenuId}-custom-skin-thickness`).style.setProperty("--percentage", percentage);
      find(`#${otherMenuId}-custom-skin-thickness-text`).value = value;
    }
    showWhiteTooltip() {
      find(".tooltip--click-custom-skin")?.remove();
      find(".tooltip--custom-skin-select")?.remove();
      const extraExplanation = "ontouchstart" in window || navigator.maxTouchPoints || this.tooltipCustomAreaShown >= 1 ? "" : `. ${translations.rotateExplain}`;
      const extraClass = extraExplanation == "" ? "" : " tooltip--custom-skin--pc";
      if (extraExplanation != "") addClass(".skin-help-js", "hide");
      const tooltipText = data(".btn--custom-skin-tool.selected", "tool") == "area" ? translations.drawSkinCustomArea : translations.drawSkinCustomBrush;
      this.messageManager.instantTooltip(
        `${tooltipText}${extraExplanation}`,
        ".viewport-container--after-1",
        `tooltip--custom-skin-select tooltip--middle-viewport font-weigtht-400 tooltip-multilines${extraClass}`,
        { seconds: 3600, onClose: () => removeClass(".skin-help-js", "hide"), id: "tooltip--custom-skin" }
      );
      if (this.tooltipCustomAreaShown < 1) {
        Ajax.put(viewerRoutes.updateViewerSettings, { viewer_settings: { custom_area_shown: this.tooltipCustomAreaShown + 1 } });
        this.tooltipCustomAreaShown++;
      }
    }
    updateSimulatedCanvas(procedure = "custom-skin") {
      const simulatedCanvas = this.references.simulator.simulatedCanvas["afterCanvas1"];
      if (simulatedCanvas.skin == null || simulatedCanvas.skin == void 0) simulatedCanvas.skin = [];
      if (this.customTreatments > 0) {
        if (!simulatedCanvas.skin.includes(procedure)) {
          simulatedCanvas.skin.push(procedure);
        }
      } else {
        simulatedCanvas.skin = simulatedCanvas.skin.filter((p2) => p2 == "skin");
      }
    }
  };

