  // app/javascript/components/viewer/fullbody/fullbody_simulator.js
  var FullbodySimulator = class extends BreastSimulator2 {
    constructor(references) {
      super(references);
      this.references.featureModifiers = this.featureModifiers = new FullbodyFeatureModifiers(references);
    }
    initialize() {
      super.initialize();
      this.cameraManager = this.references.cameraManager;
      this.covers = this.setCovers();
      on(".hide-limbs-js", "click", () => {
        toggleClass(".hide-limbs-js", "selected");
        this.hideLimbs();
        this.references.settingsManager.updateViewerSettings({ viewer_settings: { fullbody_hide_limbs: hasClass(".hide-limbs-js", "selected") } });
      });
    }
    // Only with body procedures selected
    // TODO, focus on breast for breast procedures (lines also have specific focus)
    fitCameraForProcedure() {
      if (!find(".side-menu__section-header--feature-modifier.is-open-js")) {
        this.cameraManager.fitCameraToModel(1, true);
        this.cameraManager.focusCamera("NONE");
        return;
      }
      const procedure = this.featureModifiers.selectedProcedure();
      if (procedure == "high_definition") this.cameraManager.fitCameraToArea("BODY");
      else if (procedure == "liposuction") this.cameraManager.fitCameraToArea("ABDOMEN", hasClass(".hide-limbs-js", "selected") ? 0.6 : 0.45);
      else this.cameraManager.fitCameraToArea("ABDOMEN");
      this.cameraManager.moveEngineViewForFeature();
    }
    setCovers() {
      const n2n = options.measures.nipple_to_nipple;
      let size2 = n2n / 2;
      size2 = Math.round(size2 * 10) / 10;
      return [
        { id: CoverId.RIGHT_NIPPLE, width: 5, height: 5 },
        { id: CoverId.LEFT_NIPPLE, width: 5, height: 5 },
        { id: CoverId.GROIN, width: size2, height: size2 }
      ];
    }
    hideLimbs() {
      const hideLimbs = hasClass(".hide-limbs-js", "selected");
      engine.toggleFullBodyArms(!hideLimbs);
      engine.toggleFullBodyLegs(!hideLimbs);
      this.fitCameraForProcedure();
    }
  };

