  // app/javascript/components/viewer/shape_smoothing_manager.js
  var ShapeSmoothingManager = class {
    constructor() {
    }
    initialize(references) {
      this.references = references;
      this.viewer = this.references.viewer;
      this.modalManager = this.references.modalManager;
      this.simulationsManager = this.references.simulationsManager;
      this.UIManager = this.references.UIManager;
      this.messageManager = this.references.messageManager;
      this.selectedAreas = false;
      this.errorMessage = false;
      on(".btn--toggle-shape-smoothing", "click", (e3) => {
        const target = e3.currentTarget;
        toggleClass(target, "selected");
        toggleClass(".side-menu__section--shape-smoothing-inputs", "disabled", !hasClass(target, "selected"));
        engine.toggleShapeSmoothing(hasClass(target, "selected"), "afterCanvas1");
        if (hasClass(target, "selected")) {
          engine.setShapeSmoothingRange(find("#shape-smoothing-size").value / 100);
          engine.setShapeSmoothingIntensity(find("#shape-smoothing-intensity").value / 100);
          this.messageManager.instantTooltip(
            translations.shapeSmoothingSelectAreas,
            ".viewport-container--after-1",
            "tooltip--middle-viewport tooltip--shape-smoothing-areas",
            { seconds: 10, id: "tooltip--shape-smoothing-areas" }
          );
        } else {
          document.dispatchEvent(new Event(`closeInstantTooltip-tooltip--shape-smoothing-areas`));
          engine.clearShapeSmoothingAreas();
          this.selectedAreas = false;
        }
        this.updateUI();
      });
      on("#shape-smoothing-size", "input", (e3) => {
        engine.setShapeSmoothingRange(e3.currentTarget.value / 100);
        engine.simulate("afterCanvas1");
        this.updateUI();
        if (this.simulationsManager.active.customId)
          this.simulationsManager.active.changed = true;
      });
      on("#shape-smoothing-size", "pointerdown", (e3) => {
        engine.toggleShapeSmoothingPreviewCircle("afterCanvas1", true);
      });
      on("#shape-smoothing-size", "change", (e3) => {
        engine.toggleShapeSmoothingPreviewCircle("afterCanvas1", false);
      });
      on("#shape-smoothing-intensity", "input", (e3) => {
        engine.setShapeSmoothingIntensity(e3.currentTarget.value / 100);
        this.updateUI();
        if (this.simulationsManager.active.customId)
          this.simulationsManager.active.changed = true;
      });
      on(".apply-shape-smoothing-js", "click", () => {
        engine.applyShapeSmoothing();
        engine.simulate("afterCanvas1");
        this.updateUI();
        if (this.simulationsManager.active.customId)
          this.simulationsManager.active.changed = true;
      });
      on(".clear-areas-shape-smoothing-js", "click", () => {
        engine.clearShapeSmoothingAreas();
        engine.simulate("afterCanvas1");
        this.selectedAreas = false;
        this.updateUI();
        if (this.simulationsManager.active.customId)
          this.simulationsManager.active.changed = true;
      });
      on(".delete-all-shape-smoothing-js", "click", () => {
        this.modalManager.open("reset-shape-smoothing");
      });
      on(".modal-reset-shape-smoothing-js", "click", () => {
        this.reset();
        this.modalManager.close("reset-shape-smoothing");
      });
      on(".shape-smoothing__undo", "click", () => {
        engine.undoShapeSmoothingAction("afterCanvas1");
        engine.simulate("afterCanvas1");
        this.updateUI();
        if (this.simulationsManager.active.customId)
          this.simulationsManager.active.changed = true;
      });
      on(".shape-smoothing__redo", "click", () => {
        engine.redoShapeSmoothingAction("afterCanvas1");
        engine.simulate("afterCanvas1");
        this.updateUI();
        if (this.simulationsManager.active.customId)
          this.simulationsManager.active.changed = true;
      });
      on(engine, ShapeSmoothingEvent.Type.SELECT, () => {
        document.dispatchEvent(new Event(`closeInstantTooltip-tooltip--shape-smoothing-areas`));
        this.selectedAreas = true;
        this.updateUI();
      });
      on(engine, ShapeSmoothingEvent.Type.MAX_AREAS, () => {
        if (this.errorMessage) return;
        this.errorMessage = true;
        this.messageManager.snackbar(translations.shapeSmoothingMaxAreas, { extraClasses: "snackbar--error", onClose: () => {
          this.errorMessage = false;
        } });
      });
    }
    updateUI() {
      if (!hasClass(".btn--toggle-shape-smoothing", "selected")) {
        removeClass(".side-menu__section--shape-smoothing-inputs *", "disabled");
      } else {
        toggleClass(".delete-all-shape-smoothing-js", "disabled", !engine.canDeleteAllShapeSmoothingDeformations("afterCanvas1"));
        toggleClass(".shape-smoothing__redo", "disabled", !engine.canRedoShapeSmoothingAction("afterCanvas1"));
        toggleClass(".shape-smoothing__undo", "disabled", !engine.canUndoShapeSmoothingAction("afterCanvas1"));
        toggleClass(".clear-areas-shape-smoothing-js", "disabled", !this.selectedAreas);
        toggleClass(".apply-shape-smoothing-js", "disabled", !this.selectedAreas);
        toggleClass(".shape-smoothing-intensity-wraper-js", "disabled", !this.selectedAreas);
      }
      this.references.simulator.simulatedCanvas["afterCanvas1"]["shape-smoothing"] = engine.canDeleteAllShapeSmoothingDeformations("afterCanvas1");
      if (this.viewer.isMammo()) this.references.simulator.setExportParams("afterCanvas1");
      this.UIManager.update();
    }
    withChanges() {
      return engine.canDeleteAllShapeSmoothingDeformations("afterCanvas1");
    }
    reset(simulate = true) {
      if (simulate) {
        engine.deleteAllShapeSmoothingDeformations("afterCanvas1");
        engine.simulate("afterCanvas1");
      }
      this.updateUI();
      if (this.simulationsManager.active.customId)
        this.simulationsManager.active.changed = true;
    }
  };

  // app/javascript/components/viewer/free_hand_manager.js
  var FreeHandManager = class {
    constructor() {
    }
    initialize(references) {
      this.references = references;
      this.viewer = this.references.viewer;
      this.simulationsManager = this.references.simulationsManager;
      this.modalManager = this.references.modalManager;
      this.UIManager = this.references.UIManager;
      this.messageManager = this.references.messageManager;
      this.pressingShiftKeyHandler = this.pressingShiftKey.bind(this);
      this.releasingShiftKeyHandler = this.releasingShiftKey.bind(this);
      this.touch = !window.matchMedia("(hover: hover)").matches;
      this.rotateTooltipShowed = false;
      on(".btn--toggle-free-hand", "click", (e3) => {
        const target = e3.currentTarget;
        toggleClass(target, "selected");
        const isSelected = hasClass(target, "selected");
        toggleClass(".side-menu__section--free-hand-inputs", "disabled", !isSelected);
        toggleClass(".free-hand-rotate-block-js", "hide", !isSelected);
        removeClass(".free-hand-rotate-js", "selected");
        engine.toggleFreeHand(isSelected);
        if (isSelected) {
          engine.setFreeHandRange(find("#free-hand-size").value / 100);
          if (!this.touch && !this.rotateTooltipShowed) {
            this.messageManager.instantTooltip(
              translations.rotateExplain,
              ".viewport-container--after-1",
              "tooltip--rotate",
              { seconds: 8, id: "tooltip--rotate" }
            );
            this.rotateTooltipShowed = true;
          }
          document.addEventListener("keydown", this.pressingShiftKeyHandler);
          document.addEventListener("keyup", this.releasingShiftKeyHandler);
        } else {
          document.dispatchEvent(new Event(`closeInstantTooltip-tooltip--rotate`));
          document.removeEventListener("keydown", this.pressingShiftKeyHandler);
          document.removeEventListener("keyup", this.releasingShiftKeyHandler);
        }
        this.updateUI();
      });
      on("#free-hand-size", "input", (e3) => {
        engine.setFreeHandRange(e3.currentTarget.value / 100);
        engine.simulate("afterCanvas1");
        if (this.simulationsManager.active.customId)
          this.simulationsManager.active.changed = true;
        this.updateUI();
      });
      on("#free-hand-size", "pointerdown", (e3) => {
        engine.toggleFreeHandPreviewCircle("afterCanvas1", true);
      });
      on("#free-hand-size", "change", (e3) => {
        engine.toggleFreeHandPreviewCircle("afterCanvas1", false);
      });
      on(".delete-all-free-hand-js", "click", () => {
        this.modalManager.open("reset-free-hand");
      });
      on(".modal-reset-free-hand-js", "click", () => {
        this.reset();
        this.modalManager.close("reset-free-hand");
      });
      on(".free-hand__undo", "click", () => {
        engine.undoFreeHandAction("afterCanvas1");
        engine.simulate("afterCanvas1");
        this.updateUI();
      });
      on(".free-hand__redo", "click", () => {
        engine.redoFreeHandAction("afterCanvas1");
        engine.simulate("afterCanvas1");
        if (this.simulationsManager.active.customId)
          this.simulationsManager.active.changed = true;
        this.updateUI();
      });
      on(engine, FreeHandEvent.Type.MODIFY, () => {
        if (this.simulationsManager.active.customId)
          this.simulationsManager.active.changed = true;
        this.updateUI();
        document.dispatchEvent(new Event(`closeInstantTooltip-tooltip--rotate`));
      });
      on(".free-hand-rotate-js", "click", () => this.handleRotate());
      on(".free-hand_mirror-js input", "change", (e3) => {
        engine.toggleFreeHandSymmetry(e3.currentTarget.checked);
      });
    }
    updateUI() {
      if (!hasClass(".btn--toggle-free-hand", "selected")) {
        removeClass(".side-menu__section--free-hand-inputs *", "disabled");
      } else {
        toggleClass(".delete-all-free-hand-js", "disabled", !engine.canDeleteAllFreeHandDeformations("afterCanvas1"));
        toggleClass(".free-hand__redo", "disabled", !engine.canRedoFreeHandAction("afterCanvas1"));
        toggleClass(".free-hand__undo", "disabled", !engine.canUndoFreeHandAction("afterCanvas1"));
      }
      this.references.simulator.simulatedCanvas["afterCanvas1"]["free-hand"] = this.withChanges();
      if (this.viewer.isMammo()) this.references.simulator.setExportParams("afterCanvas1");
      this.UIManager.update();
    }
    withChanges() {
      return engine.canDeleteAllFreeHandDeformations("afterCanvas1");
    }
    reset(simulate = true) {
      if (this.withChanges() && this.simulationsManager.active.customId) {
        this.simulationsManager.active.changed = true;
      }
      if (simulate) {
        engine.deleteAllFreeHandDeformations("afterCanvas1");
        engine.simulate("afterCanvas1");
      }
      this.updateUI();
    }
    handleRotate() {
      const rotateButton = find(".free-hand-rotate-js");
      toggleClass(rotateButton, "selected");
      const isSelected = hasClass(rotateButton, "selected");
      engine.toggleFreeHand(!isSelected);
    }
    pressingShiftKey(event) {
      const rotateAlreadySelected = hasClass(".free-hand-rotate-js", "selected");
      if (event.key !== "Shift" || rotateAlreadySelected) return;
      find(".free-hand-rotate-js")?.click();
    }
    releasingShiftKey(event) {
      if (event.key !== "Shift") return;
      find(".free-hand-rotate-js")?.click();
    }
  };

