  // app/javascript/components/viewer/body/body_simulator.js
  var BodySimulator2 = class extends Simulator2 {
    constructor(references) {
      super("body", references);
      this.references.featureModifiers = this.featureModifiers = new BodyFeatureModifiers(references);
    }
    initialize() {
      super.initialize();
      this.inputManager = this.references.inputManager;
      this.linesManager = this.references.linesManager;
      this.cameraManager = this.references.cameraManager;
      this.analysis = this.references.analysis;
      this.covers = this.setCovers();
    }
    withChanges() {
      return this.references.scarsManager.withChanges() || this.references.drawManager.withChanges() || this.references.cloneSkinManager.withChanges() || this.references.shapeSmoothingManager.withChanges() || this.references.featureModifiers.withChanges() || this.references.linesManager.withChanges() || this.references.freeHandManager.withChanges() || this.references.customSkinManager.withChanges();
    }
    canvasWithChanges(canvas) {
      const info = this.simulatedCanvas[canvas];
      return !!info?.body;
    }
    async reset(setDefaults = true, simulate = true) {
      if (simulate) await engine.resetSimulation("afterCanvas1");
      this.references.customSkinManager.reset(simulate);
      this.references.scarsManager.reset();
      this.references.drawManager.reset(simulate);
      this.references.cloneSkinManager.reset(simulate);
      this.references.shapeSmoothingManager.reset(simulate);
      this.featureModifiers.resetAllProcedures();
      this.linesManager.reset(false, simulate);
      this.references.freeHandManager.reset(simulate);
      this.references.customSkinManager.reset(simulate);
      this.simulatedCanvas["afterCanvas1"] = {};
      this.references.UIManager.update();
    }
    // TODO unify fullbody body part & body?
    suggestedName(canvasId) {
      let suggestedName = "";
      const simulatedCanvas = this.simulatedCanvas[canvasId];
      if (!simulatedCanvas) return suggestedName;
      const tools = ["scars", "clone-skin", "skin", "lines", "shape-smoothing", "free-hand"];
      const toolsChanges = tools.some((tool) => tool == "lines" ? !!simulatedCanvas.lines?.length : !!simulatedCanvas[tool]);
      if (!!simulatedCanvas["drawing"] && !toolsChanges && !simulatedCanvas.body)
        return translations.drawing;
      if (simulatedCanvas.body) {
        const shortened = !!suggestedName;
        for (const procedure of Object.keys(simulatedCanvas.body)) {
          if (!!suggestedName) suggestedName += " + ";
          suggestedName += translations.body_features[procedure][shortened ? `${procedure}_short` : procedure];
        }
      }
      if (toolsChanges && !suggestedName) {
        for (const tool of tools) {
          if (tool == "lines" ? !!simulatedCanvas.lines?.length : !!simulatedCanvas[tool]) {
            if (!!suggestedName) suggestedName += " + ";
            suggestedName += translations["tools"][tool];
          }
        }
      }
      return suggestedName;
    }
    fitCameraForProcedure() {
      this.cameraManager.fitCameraToModel(1, true);
      this.cameraManager.focusCamera("NONE");
    }
    setCovers() {
      const hipline = options.measures.hipline;
      let size2 = hipline / 10;
      size2 = Math.round(size2 * 10) / 10;
      return [
        { id: CoverId.GROIN, width: size2, height: size2 }
      ];
    }
    inputs() {
      return {
        lines_view: {
          type: "radio",
          input: "lines_view",
          onChange: () => {
            this.linesManager.showLines(this.inputManager.getValue("lines_view"));
          },
          onUnselect: () => {
            this.linesManager.showLines(void 0);
          }
        },
        joystick_lines: {
          type: "joystick",
          input: "stick_lines",
          resetOnUp: true,
          maxValue: 10,
          onChange: () => {
            const values = this.inputManager.getValue("joystick_lines");
            engine.updateFreeLineDeformation("afterCanvas1", {
              horizontalDisplacement: values.x,
              verticalDisplacement: values.y
            });
            engine.simulate("afterCanvas1");
          },
          onHandleDown: () => {
            engine.startFreeLineDeformation("afterCanvas1");
          },
          onHandleUp: () => {
            engine.confirmFreeLineDeformation();
          }
        },
        custom_measurements: {
          type: "radio",
          input: "custom_measurements",
          onChange: () => {
            this.references.customMeasurementsManager.setCustomMeasurement();
          },
          onUnselect: () => {
            this.analysis.showMeasurements.forEach((viewport) => {
              engine.toggleCustomMeasurementMode(viewport, CustomAssessmentMode.INTERACTABLE, false);
            });
            this.references.customMeasurementsManager.removeCustomMeasurementTooltip();
          }
        },
        body_lines_view: {
          type: "radio",
          input: "body_lines_view",
          onChange: () => {
            this.linesManager.showLines(this.inputManager.getValue("body_lines_view"));
          },
          onUnselect: () => {
            this.linesManager.showLines(void 0);
          }
        }
      };
    }
  };

  // app/javascript/components/viewer/breast/breast_analysis.js
  var BreastAnalysis = class extends Analysis {
    constructor(references) {
      super(references);
    }
    initialize() {
      super.initialize();
      on('.analysis-menu--breast .side-menu__section-header[data-procedure="volume"]', "click", (e3) => {
        const tool = (checked) => {
          return { currentTarget: { value: "areas", checked } };
        };
        this.references.UIManager.manageSectionHeaderButton(e3.currentTarget, {
          onOpen: () => {
            this.manageAssessmentMenuOrder(e3.currentTarget);
            this.topography();
            this.setHeatmap();
            this.toggleCustomMeasurementsVisibility("all", false);
            this.updateTool(tool(true));
            this.toggleCustomMeasurementsVisibility("areas", !!!find("#hide-custom-areas:checked"));
            engine.deselectCustomMeasurementLine();
            if (this.viewer.isBody()) this.references.cameraManager.fitCameraToArea("BREAST");
          },
          onClose: () => {
            this.updateTool(tool(false));
            this.toggleCustomMeasurementsVisibility("areas", false);
            engine.deselectCustomMeasurementLine();
            if (this.viewer.isBody()) {
              this.references.cameraManager.fitCameraToModel(1, true);
              this.references.cameraManager.focusCamera("NONE");
            }
          }
        });
      });
      on('.analysis-menu--breast .side-menu__section-header[data-procedure="measurements"]', "click", (e3) => {
        const tool = (checked) => {
          return { currentTarget: { value: "measurements", checked } };
        };
        this.getLinesVisibilityViewports(data(".analysis-mode-js .selected", "target"));
        this.references.UIManager.manageSectionHeaderButton(e3.currentTarget, {
          onOpen: () => {
            this.manageAssessmentMenuOrder(e3.currentTarget);
            this.topography();
            this.setHeatmap();
            this.toggleCustomMeasurementsVisibility("all", false);
            const breastMeasurementsChecked = find("#measurements-predefined").checked && find(".measurements-predefined-js input:checked");
            const bodyMeasurementsChecked = find("#measurements-predefined-body").checked;
            if (breastMeasurementsChecked) this.updateTool({ currentTarget: { value: find(".measurements-predefined-js input:checked").value, checked: true } });
            if (bodyMeasurementsChecked) this.updateTool({ currentTarget: { value: find('[name="measurements-body"]:checked').value, checked: true } });
            if (!breastMeasurementsChecked && !bodyMeasurementsChecked) this.updateTool(tool(true));
            this.toggleCustomMeasurementsVisibility("measurements", !!find("#measurements-custom:checked"));
            engine.deselectCustomMeasurementLine();
            if (this.viewer.isBody()) this.references.cameraManager.fitCameraToArea("BODY", 0.8);
          },
          onClose: () => {
            this.updateTool(tool(false));
            this.toggleCustomMeasurementsVisibility("measurements", false);
            engine.deselectCustomMeasurementLine();
            if (this.viewer.isBody()) {
              this.references.cameraManager.fitCameraToModel(1, true);
              this.references.cameraManager.focusCamera("NONE");
            }
          }
        });
      });
      on('.analysis-menu--breast .side-menu__section-header[data-procedure="topography"]', "click", (e3) => {
        const tool = (checked) => {
          return { currentTarget: { value: "measurements", checked } };
        };
        this.getLinesVisibilityViewports(data(".analysis-mode-js .selected", "target"));
        this.references.UIManager.manageSectionHeaderButton(e3.currentTarget, {
          onOpen: () => {
            this.manageAssessmentMenuOrder(e3.currentTarget);
            this.setHeatmap();
            this.updateTool(tool(false));
            this.toggleCustomMeasurementsVisibility("measurements", false);
            this.toggleCustomMeasurementsVisibility("areas", false);
            engine.deselectCustomMeasurementLine();
            this.topography();
          },
          onClose: () => {
            this.topography();
          }
        });
      });
      on('.analysis-menu--breast .side-menu__section-header[data-procedure="heatmap"]', "click", (e3) => {
        const tool = (checked) => {
          return { currentTarget: { value: "heatmap", checked } };
        };
        this.getLinesVisibilityViewports(data(".analysis-mode-js .selected", "target"));
        this.references.UIManager.manageSectionHeaderButton(e3.currentTarget, {
          onOpen: () => {
            this.manageAssessmentMenuOrder(e3.currentTarget);
            this.toggleCustomMeasurementsVisibility("all", false);
            this.updateTool(tool(false));
            toggleClass(".heatmap-with-changes", "hide", !this.simulator.withChanges());
            toggleClass(".heatmap-without-changes", "hide", this.simulator.withChanges());
            this.setHeatmap();
          },
          onClose: () => {
            this.setHeatmap();
          }
        });
      });
      on("#projection-adjustment, #angle-projection", "input", () => {
        removeClass(".measurements-js .btn--reset-predefined", "disabled");
        engine.adjustTriangleAssessmentPlanePositionAndRotation(+find("#projection-adjustment").value * -1, +find("#angle-projection").value);
      });
      on("#quadrants", "change", (e3) => {
        engine.toggleBreastAreaTags(false, e3.currentTarget.checked);
      });
      on("#breast-topography-skin, #breast-topography-distances, #breast-topography-m-line", "change", () => {
        this.topography();
      });
      on(".side-menu__switch--topography button", "click", (event) => {
        const target = event.currentTarget;
        if (hasClass(target, "selected")) {
          removeClass(target, "selected");
          addClass(".topography-radio-container", "hide");
        } else {
          removeClass(".side-menu__switch--topography button", "selected");
          addClass(target, "selected");
          addClass(".topography-radio-container", "hide");
          data(target, "target");
          if (data(target, "target") != "distances") {
            removeClass(".topography-radio-container--" + data(target, "target"), "hide");
          }
        }
        this.topography();
      });
      on(".topography-radio-container input", "change", () => this.topography());
      on(".btn--topography-export", "click", () => this.topographyExportJSON());
      on("#heatmap-areas, #heatmap-areas-distance, #heatmap-volume-regions", "change", () => {
        this.setHeatmap();
      });
    }
    topography(forceDisable = false) {
      const menuOpen = this.topographyOpen();
      const enable = forceDisable ? false : menuOpen;
      const distance = this.references.inputManager.getValue("breast_topography_interval");
      const thickness = 0.3;
      const viewportTarget = data(".analysis-mode-js button.selected", "target");
      const hideSkin = !find("#breast-topography-skin:checked");
      const tags = !!find('.side-menu__switch--topography button[data-target="distances"].selected') || !!find("#breast-topography-distances:checked");
      const mLine = !!find("#breast-topography-m-line:checked") && enable;
      const segmentSelected = !!find('.side-menu__switch--topography button[data-target="segments"].selected', "target");
      const anglesSelected = !!find('.side-menu__switch--topography button[data-target="angles"].selected', "target");
      const totalAngles = {
        upper: anglesSelected && !!find('.topography-radio-container--angles input[value="upper"]:checked'),
        lower: anglesSelected && !!find('.topography-radio-container--angles input[value="lower"]:checked'),
        inner: anglesSelected && !!find('.topography-radio-container--angles input[value="inner"]:checked'),
        outer: anglesSelected && !!find('.topography-radio-container--angles input[value="outer"]:checked')
      };
      const segments = {
        upper: segmentSelected && !!find('.topography-radio-container--segments input[value="upper"]:checked') ? BreastTopographySegmentMode.ID : BreastTopographySegmentMode.NONE,
        lower: segmentSelected && !!find('.topography-radio-container--segments input[value="lower"]:checked') ? BreastTopographySegmentMode.ID : BreastTopographySegmentMode.NONE,
        inner: segmentSelected && !!find('.topography-radio-container--segments input[value="inner"]:checked') ? BreastTopographySegmentMode.ID : BreastTopographySegmentMode.NONE,
        outer: segmentSelected && !!find('.topography-radio-container--segments input[value="outer"]:checked') ? BreastTopographySegmentMode.ID : BreastTopographySegmentMode.NONE
      };
      let viewportQuery = ".viewport-container--active";
      if (viewportTarget === "after" && enable) {
        viewportQuery = ".viewport-container--after.viewport-container--active";
      } else if (viewportTarget === "before" && enable) {
        viewportQuery = ".viewport-container--before";
      }
      addClass(".legend--topography", "hide");
      findAll(viewportQuery).forEach((viewport) => {
        const canvas = viewport.querySelector("canvas");
        engine.setBreastTopographyParameters(canvas.id, {
          left: {
            enable,
            distance,
            thickness,
            tags,
            totalAngles,
            segments
          },
          right: {
            enable,
            distance,
            thickness,
            tags,
            totalAngles,
            segments
          }
        });
        if (!forceDisable && hideSkin && menuOpen) engine.toggleSkin(false, canvas.id);
        else engine.toggleSkin(true, canvas.id);
        this.toggleTopographyLegend(viewport, enable);
        engine.togglePredefinedMeasurements(canvas.id, mLine ? [MeasurementType.BREAST_M_LINE] : [], PredefinedAssessmentMode.INTERACTABLE);
      });
    }
    reset(removingAreas = false) {
      super.reset(removingAreas);
      this.topography();
    }
    handleAnalysisMode(event) {
      super.handleAnalysisMode(event);
      if (this.topographyOpen()) {
        this.topography(true);
        this.topography();
      }
    }
    toggleTopographyLegend(viewport, enable) {
      const canvas = viewport.querySelector("canvas");
      toggleClass(viewport.querySelector(".legend--topography"), "hide", !enable);
      const maxObj = engine.getBreastTopographyDistanceLimit(canvas.id);
      let max3 = maxObj.right > maxObj.left ? maxObj.right : maxObj.left;
      setLegendValues(viewport.querySelector(".legend--topography"), max3);
    }
    topographyOpen() {
      return !!find('.analysis-menu--breast .side-menu__section-header.is-open-js[data-procedure="topography"]');
    }
    topographyExportJSON() {
      const data2 = engine.exportBreastTopographyData("afterCanvas1");
      const topographyData = {
        left: {
          segments: data2.left.segments,
          totalAngles: data2.left.totalAngles
        },
        right: {
          segments: data2.right.segments,
          totalAngles: data2.right.totalAngles
        }
      };
      const jsonStr = JSON.stringify(topographyData, null, 2);
      const blob = new Blob([jsonStr], { type: "application/json" });
      const url2 = URL.createObjectURL(blob);
      const a2 = find(".topography-export-download-js");
      a2.href = url2;
      a2.click();
    }
    hideCurrentAssessment() {
      if (this.topographyOpen()) this.topography(true);
      else {
        super.hideCurrentAssessment();
      }
    }
    showCurrentAssessment(target = "both") {
      if (this.topographyOpen()) this.topography();
      else {
        super.showCurrentAssessment(target);
      }
    }
  };

