  // app/javascript/components/viewer/face/implantech_manager.js
  var ImplantechManager = class {
    constructor() {
    }
    initialize(references) {
      this.references = references;
      this.currentImplants = {
        chin: this.defaultImplantParams(),
        midfacial: {
          right: this.defaultImplantParams(),
          left: this.defaultImplantParams()
        },
        nasal: this.defaultImplantParams()
      };
      addClass("#implantech-intensity", "disabled");
      addClass("#implantech-rotation", "disabled");
      addClass(".implantech__details-dropdown--more", "disabled");
      addClass(".side-menu__implantech-section-js .checkbox-switch", "disabled");
      on(".implant-catalog--implantech__tabs button", "click", (e3) => {
        const target = e3.currentTarget;
        const type2 = data(target, "type");
        removeClass(".implant-catalog--implantech__tabs button.selected", "selected");
        addClass(".implant-catalog--implantech__container .implant-catalog__results-list", "hide");
        removeClass(`.implant-catalog--implantech__container .implant-catalog__results-list[data-type="${type2}"]`, "hide");
        addClass(target, "selected");
        toggleClass(".implant-catalog--implantech__asymmetry", "hide", type2 !== "midfacial");
        if (this.getCurrentImplant(type2).id) {
          addClass(`.implant-catalog--implantech__implant-card[data-id="${this.getCurrentImplant(type2).id}"]`, "selected");
          this.printSize(implantech_default.find((implant) => implant.id == this.getCurrentImplant(type2).id), this.getCurrentImplant(type2).size);
          this.setSliders(this.getCurrentImplant(type2).intensity, this.getCurrentImplant(type2).rotation.x);
          removeClass(".joystick-wrapper--implant", "hide");
          removeClass("#implantech-intensity", "disabled");
          removeClass("#implantech-rotation", "disabled");
          removeClass(".side-menu__implantech-section-js .checkbox-switch", "disabled");
        } else {
          const checkedSizeInput = find('input[name="implantech_size"]:checked');
          if (checkedSizeInput) checkedSizeInput.checked = false;
          addClass(".input-group--implantech-size .input-group--radio__item", "disabled");
          addClass(".joystick-wrapper--implant", "hide");
          addClass("#implantech-intensity", "disabled");
          addClass("#implantech-rotation", "disabled");
          addClass(".side-menu__implantech-section-js .checkbox-switch", "disabled");
          this.setSliders(1, 0);
        }
        this.rotateCamera();
        this.updateDetails();
      });
      on("#implantech-show-implants", "change", (e3) => {
        engine.toggleImplantVisualization(e3.currentTarget.checked);
      });
      on("#implantech-intensity, #implantech-rotation", "input change", (e3) => {
        const target = e3.currentTarget;
        const initial = data(target, "initial");
        toggleClass(`.btn--reset-${target.id}`, "disabled", target.value === initial);
        this.applyImplant();
      });
      on(".btn--reset-implantech-intensity", "click", () => {
        resetSlider("implantech-intensity", 1);
        addClass(".btn--reset-implantech-intensity", "disabled");
        this.applyImplant();
      });
      on(".btn--reset-implantech-rotation", "click", () => {
        resetSlider("implantech-rotation", 0);
        addClass(".btn--reset-implantech-rotation", "disabled");
        this.applyImplant();
      });
      on('input[name="implantech_asymmetry"]', "change", () => {
        this.rotateCamera();
        const type2 = data(".implant-catalog--implantech__tabs button.selected", "type");
        removeClass('.implant-catalog__results-list[data-type="midfacial"] .implant-catalog--implantech__implant-card.selected', "selected");
        const asymmetry = find('input[name="implantech_asymmetry"]:checked').value;
        const leftImplant = this.currentImplants.midfacial.left;
        const rightImplant = this.currentImplants.midfacial.right;
        let targetImplant = { id: null };
        if (asymmetry === "none") {
          if (leftImplant.id === rightImplant.id) {
            targetImplant = this.getCurrentImplant(type2);
          }
        } else {
          targetImplant = this.getCurrentImplant(type2);
        }
        if (targetImplant.id) {
          addClass(`.implant-catalog--implantech__implant-card[data-id="${targetImplant.id}"]`, "selected");
          this.printSize(implantech_default.find((implant) => implant.id == targetImplant.id), targetImplant.size);
          this.setSliders(targetImplant.intensity, targetImplant.rotation.x);
          removeClass(".joystick-wrapper--implant", "hide");
          removeClass("#implantech-intensity", "disabled");
          removeClass("#implantech-rotation", "disabled");
          removeClass(".side-menu__implantech-section-js .checkbox-switch", "disabled");
        } else {
          const checkedSizeInput = find('input[name="implantech_size"]:checked');
          if (checkedSizeInput) checkedSizeInput.checked = false;
          addClass(".input-group--implantech-size .input-group--radio__item", "disabled");
          addClass(".joystick-wrapper--implant", "hide");
          addClass("#implantech-intensity", "disabled");
          addClass("#implantech-rotation", "disabled");
          addClass(".side-menu__implantech-section-js .checkbox-switch", "disabled");
          this.setSliders(1, 0);
        }
        this.updateDetails();
      });
      on(".implantech__details-dropdown", "click", () => {
        this.toggleDetails(!hasClass(".implantech__details-dropdown--more", "hide"));
      });
      this.initializeJoystick();
    }
    toggleCatalog(show2 = null) {
      toggleClass(".implant-catalog--implantech__container", "hide", show2 == null ? show2 : !show2);
      const opened = !hasClass(".implant-catalog--implantech__container", "hide");
      toggleClass(".simulator", "simulator--implant-catalog", opened);
      if (opened) {
        const type2 = data(".implant-catalog--implantech__tabs button.selected", "type");
        if (this.getCurrentImplant(type2).id) {
          removeClass(".joystick-wrapper--implant", "hide");
        }
        this.rotateCamera();
      } else {
        addClass(".joystick-wrapper--implant", "hide");
      }
    }
    async loadImplants() {
      if (!find(".side-menu__section-header--implantech")) return;
      const engineImplants = {};
      for (const type2 of ["chin", "midfacial", "nasal"]) {
        const implants = implantech_default.filter((implant) => implant.type === type2);
        let list2 = "";
        for (const implant of implants) {
          list2 += render("implantechImplantCard", { ...implant, image: implantechImages[implant.id] });
          if (implant.symmetric) {
            for (const size2 of implant.size) {
              engineImplants[`${implant.type}_${implant.reference.toLowerCase()}_${size2.toLowerCase()}`] = {
                region: ImplantRegion[implant.type.toUpperCase()],
                type: ImplantType[implant.reference.toUpperCase()],
                meshUrl: `/implantech/${implant.reference.toUpperCase()}-${size2.toUpperCase()}.k3d`
              };
            }
          } else {
            for (const side of ["left", "right"]) {
              for (const size2 of implant.size) {
                engineImplants[`${implant.type}_${implant.reference.toLowerCase()}_${size2.toLowerCase()}_${side}`] = {
                  region: ImplantRegion[`${implant.type}_${side}`.toUpperCase()],
                  type: ImplantType[`${implant.reference}_${side}`.toUpperCase()],
                  meshUrl: `/implantech/${implant.reference.toUpperCase()}-${size2.toUpperCase()}-${side}.k3d`
                };
              }
            }
          }
        }
        insertHTML(`.implant-catalog__results-list[data-type="${type2}"]`, list2);
      }
      engine.toggleImplantVisualization(true);
      await engine.loadImplants(engineImplants);
      on(".implant-catalog--implantech__implant-card", "click", (e3) => {
        this.selectImplant(data(e3.currentTarget, "id"));
      });
      removeClass(".side-menu__section-header--implantech", "disabled");
    }
    selectImplant(implantId) {
      const implant = implantech_default.find((implant2) => implant2.id == implantId);
      const currentImplantId = data(".implant-catalog--implantech__implant-card.selected", "id");
      if (currentImplantId == implantId) {
        removeClass(".implant-catalog--implantech__implant-card.selected", "selected");
        if (implant.symmetric) {
          this.removeImplant(implant.type);
        } else {
          const currentAsymmetry = find('input[name="implantech_asymmetry"]:checked').value;
          if (currentAsymmetry === "none") {
            this.removeImplant(`${implant.type}_left`);
            this.removeImplant(`${implant.type}_right`);
          } else {
            this.removeImplant(`${implant.type}_${currentAsymmetry}`);
          }
        }
        const checkedSizeInput = find('input[name="implantech_size"]:checked');
        if (checkedSizeInput) checkedSizeInput.checked = false;
        addClass(".input-group--implantech-size .input-group--radio__item", "disabled");
        addClass(".joystick-wrapper--implant", "hide");
        addClass("#implantech-intensity", "disabled");
        addClass("#implantech-rotation", "disabled");
        addClass(".side-menu__implantech-section-js .checkbox-switch", "disabled");
        this.setSliders(1, 0);
        engine.simulate("afterCanvas1");
        this.setCurrentImplants(implant.type, implant.symmetric, this.defaultImplantParams());
        if (implant.type === "midfacial") {
          if (!this.currentImplants.midfacial.left.id && !this.currentImplants.midfacial.right?.id)
            removeClass(`.implant-catalog--implantech__tabs .btn[data-type=${implant.type}]`, "btn--edited");
        } else
          removeClass(`.implant-catalog--implantech__tabs .btn[data-type=${implant.type}]`, "btn--edited");
        if (!this.withChanges())
          removeClass(".side-menu__section-header--implantech", "edited");
        this.updateDetails();
        this.references.UIManager.update();
        return;
      } else if (currentImplantId) {
        removeClass(".implant-catalog--implantech__implant-card.selected", "selected");
        this.setSliders(1, 0);
      }
      addClass(`.implant-catalog--implantech__tabs .btn[data-type=${implant.type}]`, "btn--edited");
      removeClass(".joystick-wrapper--implant", "hide");
      removeClass("#implantech-intensity", "disabled");
      removeClass("#implantech-rotation", "disabled");
      removeClass(".side-menu__implantech-section-js .checkbox-switch", "disabled");
      this.printSize(implant);
      addClass(`.implant-catalog--implantech__implant-card[data-id="${implantId}"]`, "selected");
      this.rotateCamera();
      this.applyImplant();
      this.updateDetails();
      this.references.UIManager.update();
    }
    removeImplant(type2) {
      engine.removeImplant("afterCanvas1", ImplantRegion[type2.toUpperCase()]);
    }
    applyImplant() {
      const type2 = data(".implant-catalog--implantech__tabs button.selected", "type");
      const implantElem = find(`.implant-catalog__results-list[data-type="${type2}"] .implant-catalog--implantech__implant-card.selected`);
      const implantId = data(implantElem, "id");
      const implant = implantech_default.find((implant2) => implant2.id == implantId);
      const size2 = find('input[name="implantech_size"]:checked').value;
      const intensity = parseFloat(find("#implantech-intensity").value);
      const rotation = parseFloat(find("#implantech-rotation").value);
      const displacement2 = this.joystick.value;
      let engineImplantId = `${implant.type}_${implant.reference.toLowerCase()}_${size2.toLowerCase()}`;
      if (implant.symmetric) {
        engine.setImplantParameters("afterCanvas1", { id: engineImplantId, intensity, displacement: displacement2, rotation: { x: rotation, y: 0, z: 0 } });
      } else {
        const asymmetry = find('input[name="implantech_asymmetry"]:checked').value;
        if (asymmetry === "none") {
          const rightDisplacement = { x: -displacement2.x, y: displacement2.y };
          engine.setImplantParameters("afterCanvas1", { id: `${engineImplantId}_right`, intensity, displacement: rightDisplacement, rotation: { x: rotation, y: 0, z: 0 } });
          engine.setImplantParameters("afterCanvas1", { id: `${engineImplantId}_left`, intensity, displacement: displacement2, rotation: { x: rotation, y: 0, z: 0 } });
        } else {
          engine.setImplantParameters("afterCanvas1", { id: `${engineImplantId}_${asymmetry}`, intensity, displacement: displacement2, rotation: { x: rotation, y: 0, z: 0 } });
        }
      }
      this.setCurrentImplants(implant.type, implant.symmetric, { id: implantId, size: size2, intensity, displacement: displacement2, rotation: { x: rotation, y: 0, z: 0 } });
      engine.simulate("afterCanvas1");
    }
    printSize(implant, size2 = null) {
      const sizes = implant.size;
      let buttons = "";
      for (const size3 of sizes) {
        buttons += render("implantechSizeButton", { size: size3.toLowerCase(), text: size3.toUpperCase() });
      }
      insertHTML(".input-group--implantech-size .input-group--radio__input", buttons);
      if (size2)
        find(`input[name="implantech_size"][value="${size2.toLowerCase()}"]`).checked = true;
      else
        find('input[name="implantech_size"]').checked = true;
      on('input[name="implantech_size"]', "change", () => {
        this.applyImplant();
        this.updateDetails();
      });
    }
    setSliders(intensity, rotation) {
      resetSlider("implantech-intensity", intensity);
      resetSlider("implantech-rotation", rotation);
    }
    initializeJoystick() {
      const container = findParent("#stick", ".joystick");
      const joystickSize = parseInt(getComputedStyle(container).width);
      this.joystick = new Joystick("stick", joystickSize / 2, 1, 1, true);
      on("#stick", "joystickmove", () => {
        this.applyImplant();
      });
    }
    withChanges() {
      const { chin, midfacial, nasal } = this.currentImplants;
      if (chin && chin.id !== null) return true;
      if (nasal && nasal.id !== null) return true;
      if (midfacial && (midfacial.left.id !== null || midfacial.right.id !== null)) return true;
      return false;
    }
    reset() {
      engine.removeAllImplants("afterCanvas1");
      this.setCurrentImplants("chin", true, this.defaultImplantParams());
      this.setCurrentImplants("midfacial", false, this.defaultImplantParams());
      this.setCurrentImplants("nasal", true, this.defaultImplantParams());
      removeClass(".implant-catalog--implantech__implant-card.selected", "selected");
      const checkedSizeInput = find('input[name="implantech_size"]:checked');
      if (checkedSizeInput) checkedSizeInput.checked = false;
      removeClass(".implant-catalog--implantech__tabs .btn", "btn--edited");
      removeClass(".side-menu__section-header--implantech", "edited");
      addClass(".input-group--implantech-size .input-group--radio__item", "disabled");
      addClass(".joystick-wrapper--implant", "hide");
      addClass("#implantech-intensity", "disabled");
      addClass("#implantech-rotation", "disabled");
      addClass(".side-menu__implantech-section-js .checkbox-switch", "disabled");
      this.setSliders(1, 0);
      this.updateDetails();
    }
    setCurrentImplants(type2, symmetry, values) {
      if (symmetry) {
        this.currentImplants[type2] = values;
      } else {
        const currentAsymmetry = find('input[name="implantech_asymmetry"]:checked').value;
        if (currentAsymmetry !== "none") {
          this.currentImplants[type2][currentAsymmetry] = values;
        } else {
          this.currentImplants[type2]["left"] = values;
          this.currentImplants[type2]["right"] = values;
        }
      }
    }
    getCurrentImplant(type2) {
      if (type2 === "midfacial") {
        const currentAsymmetry = find('input[name="implantech_asymmetry"]:checked').value;
        if (currentAsymmetry !== "none") {
          return this.currentImplants[type2][currentAsymmetry];
        } else {
          return this.currentImplants[type2]["right"];
        }
      }
      return this.currentImplants[type2];
    }
    rotateCamera() {
      const type2 = data(".implant-catalog--implantech__tabs button.selected", "type");
      if (["chin", "nasal"].includes(type2))
        lookLeft();
      else {
        const asymmetry = find('input[name="implantech_asymmetry"]:checked').value;
        if (asymmetry === "none")
          lookFront();
        else if (asymmetry === "left")
          lookRight45();
        else if (asymmetry === "right")
          lookLeft45();
      }
    }
    defaultImplantParams() {
      return { id: null, size: null, intensity: 1, rotation: { x: 0, y: 0, z: 0 }, displacement: { x: 0, y: 0 } };
    }
    toggleDetails(open2) {
      toggleClass(".implantech__details-dropdown--more", "hide", open2);
      toggleClass(".implantech__details-dropdown--less", "hide", !open2);
      toggleClass(".implantech__details-container", "hide", !open2);
    }
    updateDetails() {
      const type2 = data(".implant-catalog--implantech__tabs button.selected", "type");
      const implant = this.getCurrentImplant(type2);
      if (implant.id) {
        const implantData = implantech_default.find((i3) => +i3.id === +implant.id);
        const detailsImage = find(".implantech__details-image img");
        const size2 = find('input[name="implantech_size"]:checked').value.toUpperCase();
        let legendHTML = "";
        detailsImage.src = implantechDetailsImages[implantData.id];
        removeClass(".implantech__details-dropdown--more", "disabled");
        insertHTML(".implantech__details-description", translations.implantech[implantData.reference.toLowerCase()]);
        for (const [key, value] of Object.entries(implantData.sizeMeasures[size2])) {
          legendHTML += `<div><span>${key}</span><span>${value} ${implantData.sizeUnit}</span></div>`;
        }
        insertHTML(".implantech__details-legend", legendHTML);
      } else {
        this.toggleDetails(false);
        addClass(".implantech__details-dropdown--more", "disabled");
      }
    }
  };

